INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('星域奇航 (Star Realms)','20 min','12+','2 人',NULL,'快節奏的星際戰爭遊戲。玩家透過購買卡牌來強化自己的艦隊與基地，目標是將對手的影響力（血量）削減至零。'),
	 ('字字轉機 (Anomia)','20-30 min','9+','3-6 人','bg_1774760410614.jpeg','考驗反應力與詞彙聯想。當兩名玩家的卡牌圖案相同時，必須搶先喊出對方卡牌類別的相關詞彙（如：水果、品牌名）。'),
	 ('動物方程式 (Zootopia / Animal Strategy)','20 min','6+','2-4 人',NULL,'以可愛動物為主題的移動與占領遊戲，適合親子同樂，透過簡單的規則學習空間規劃與初級邏輯。'),
	 ('瞎掰王 (The Liars)','30-45 min','9+','3-9 人','bg_1774760330851.jpeg','玩家需針對冷知識進行說明。只有一人知道正確答案，其他人必須一本正經地胡說八道，騙取其他人的信任票。'),
	 ('瞎掰王-接著掰','30-45 min','9+','3-9 人',NULL,'《瞎掰王》的續作/擴充，加入了更多荒謬、難以置信的冷僻詞彙，讓玩家的胡說八道功力再次升級。'),
	 ('5秒定律 (5 Second Rule)','20-30 min','9+','3-6 人',NULL,'題目很簡單，例如「說出三個台灣地名」，但你只有 5 秒鐘！在時間壓力下，玩家往往會說出令人捧腹大笑的胡言亂語。'),
	 ('試個好遊戲 (We Didn''t Playtest This at All)','1-5 min','12+','2-10 人',NULL,'這是一款完全不按牌理出牌的遊戲。規則隨時會變，你可能因為身為男生、或是摸了鼻子就突然出局，充滿混亂與驚喜。'),
	 ('德國蟑螂 (Kakerlakenpoker)','15-25 min','9+','2-6 人',NULL,'經典的吹牛遊戲。玩家傳遞討厭的生物卡（如蟑螂、蒼蠅），並宣告其種類，對方要猜你是否在說謊。猜錯的人就得收下這張牌。'),
	 ('大頭娃娃 (Toddles-Bobbles)','15-20 min','6+','2-6 人',NULL,'為出現的奇怪生物取名！下次當相同的生物出現時，誰先喊出正確的名字就能贏得卡片，考驗創意與記憶力。'),
	 ('病毒在跳舞 (Virus!)','15-20 min','9+','2-6 人',NULL,'目標是率先收集四個健康的器官。玩家可以透過病毒卡攻擊對手，或使用疫苗護理自己的器官，是一款快節奏的互相傷害遊戲。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('Moo斯密碼 (Moo''s Code)','15-20 min','6+','3-6 人',NULL,'一名玩家扮演牛大師，用敲擊聲代表摩斯密碼，其他玩家要根據節奏聽出對應的動物卡片，是一款非常可愛的節奏遊戲。'),
	 ('作弊飛蛾 (Cheating Moth)','15-25 min','6+','3-5 人',NULL,'這是一款「鼓勵」你作弊的遊戲！除了一名守衛玩家外，其他人必須設法把手牌藏進袖子、丟到桌下，只要不被抓到，怎麼作弊都可以。'),
	 ('面積對決 (Face to Face)','20 min','9+','2-6 人',NULL,'透過簡單的圖塊拼接，玩家要在有限的棋盤上爭奪最大的領地，考驗基本的幾何觀察與預判對手落點的能力。'),
	 ('馬戲經理人 (Circus Flohcati)','15 min','6+','2-5 人',NULL,'由桌遊大師 Reiner Knizia 設計。玩家要翻開卡牌招募馬戲團表演者，翻得越多風險越高，考驗玩家「見好就收」的勇氣。'),
	 ('驚爆倫敦 (Time Bomb)','15-30 min','9+','4-8 人',NULL,'福爾摩斯與莫里亞蒂的對決。警察方要在限時內剪斷黃線拆除炸彈，而恐怖分子要引導警察剪到紅線讓倫敦爆炸。'),
	 ('驚爆倫敦-秘密任務 (Time Bomb: Evolution)','15-30 min','9+','4-8 人',NULL,'經典《驚爆倫敦》的進階版，加入了多種色彩不同的炸彈，增加了拆彈難度與陣營偽裝的深度。'),
	 ('快手疊杯 (Speed Cups)','15 min','6+','2-4 人',NULL,'看著挑戰卡上的圖案（如五色火車或花朵），玩家要以最快速度將手中的五色杯子橫向排列或垂直堆疊，並搶先按鈴。'),
	 ('德國心臟病 (Halli Galli)','15 min','6+','2-6 人',NULL,'桌上出現五顆同種水果時，就要瘋狂按鈴！考驗眼力與手速，是全球最知名的反應類派對桌遊之一。'),
	 ('衰事會發生 (Shit Happens)','20-30 min','18+','2-10 人',NULL,'遊戲內含各種倒楣事，玩家要根據「痛苦指數」將其排在正確的位置。由於內容包含許多成人幽默與尷尬情境，建議成年人遊玩。'),
	 ('衰事無極限 (Shit Happens: Too Much Information)','20-30 min','18+','2-10 人',NULL,'《衰事會發生》的系列作，收錄了更多難堪、噁心或令人尷尬的日常衰事，挑戰你的價值觀邊界。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('腦洞量表 (Top Ten)','20-30 min','15+','4-9 人',NULL,'隊長出一個題目（如：形容一個屁的味道），玩家要根據手中抽到的 1-10 數字強度來即興發揮，隊長需猜出大家的數字順序。'),
	 ('腦洞量表-沒有下限','20-30 min','18+','4-9 人',NULL,'《腦洞量表》的深夜版本。題目更加露骨與重口味，適合在只有成人的聚會中釋放本性。'),
	 ('字母風火輪 (Tapple)','10-20 min','9+','2-8 人',NULL,'給定一個分類（如：水果），玩家要在 10 秒內說出該字母開頭的詞並按壓對應鍵，被按過的字母就不能再用，節奏非常緊湊。'),
	 ('沃塔棋 (Volterra)','15 min','9+','2 人',NULL,'優美的雙人對弈遊戲。玩家交替放置或移動圓柱，目標是在棋盤上建立最高的高塔並佔領它，極具禪意與邏輯深度。'),
	 ('UNO疊疊樂 (UNO Stacko)','15-20 min','6+','2-4 人',NULL,'融合了 UNO 規則與疊疊樂。玩家要抽取出跟上一位玩家同顏色或同數字的木條，並疊到頂端，弄倒塔的人就輸了。'),
	 ('形色叩叩 (Qwirkle)','30-45 min','6+','2-4 人',NULL,'類似拼字遊戲的邏輯。玩家要放下顏色相同但形狀不同，或是形狀相同但顏色不同的方塊，拼出 6 個一組的 Qwirkle 來獲得高分。'),
	 ('籤籤入扣 (Stick Stack)','15 min','9+','2-8 人',NULL,'玩家需將彩色的塑膠籤放在搖晃的塔頂，規則是籤的顏色必須碰到支架或其他籤上的相同顏色。只要籤掉下來就要收回扣分。'),
	 ('UNO','15-30 min','6+','2-10 人',NULL,'全世界最知名的卡牌遊戲之一。目標是率先出完手中的牌，出剩最後一張時要大喊「UNO！」。'),
	 ('UNO Flip!','20-30 min','6+','2-10 人',NULL,'UNO 的進化版，牌面有正反兩面。當有人打出翻轉牌時，所有玩家必須將手牌翻面，暗黑面的處罰比普通面更殘酷！'),
	 ('大搜查 (Unlock!)','60 min','9+','1-6 人',NULL,'搭配專屬 App 的密室逃脫桌遊。玩家需透過觀察卡牌上的線索、組合物品及解鎖密碼，在限時一小時內逃出生天。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('大搜查-擴充','60 min','9+','1-6 人',NULL,'包含額外的劇本與謎題，延續《大搜查》系列核心玩法，提供更多不同主題與難度的解謎挑戰。'),
	 ('腦洞量表-大冒險','20-30 min','9+','4-9 人',NULL,'延續《腦洞量表》的玩法，但題目更偏向肢體展現或高難度的尷尬挑戰，增加了遊戲的動態樂趣。'),
	 ('大搜查-英勇冒險 (Unlock! Heroic Adventures)','60 min','9+','1-6 人',NULL,'內含三個劇本：福爾摩斯案件、電動遊戲世界以及愛麗絲夢遊仙境。結合了更多數位互動元素。'),
	 ('大搜查-史詩冒險 (Unlock! Epic Adventures)','60 min','9+','1-6 人',NULL,'包含：第七藝術（電影主題）、七道考驗與黃金龍之怒。難度適中，劇情轉折極具戲劇性。'),
	 ('大搜查-絕密冒險 (Unlock! Secret Adventures)','60 min','9+','1-6 人',NULL,'以特務間諜與懸疑案件為核心，玩家需在重重陷阱中尋找真相，考驗細心的觀察力與邏輯推演。'),
	 ('大搜查-異域冒險 (Unlock! Exotic Adventures)','60 min','9+','1-6 人',NULL,'充滿奇幻色彩與科幻風格的場景，包含恐龍主題與異世界探索，谜題設計較為新穎大膽。'),
	 ('利曼24小時耐力賽 (Le Mans 24)','20-30 min','9+','2-5 人',NULL,'模擬賽車耐力賽。玩家需平衡賽車的速度與零件的損耗，在長程賽事中判斷何時進站維修，目標是最先衝過終點。'),
	 ('蟲蟲燒烤派對 (Pickomino)','20-30 min','9+','2-7 人',NULL,'由 Reiner Knizia 設計。玩家擲骰收集數字，目標是贏得美味的蟲蟲餅乾，還能搶奪對手的食物，是一款輕快爆笑的骰子遊戲。'),
	 ('罩得住 (Cover Your Assets)','20-45 min','6+','2-6 人',NULL,'玩家透過收集資產卡來致富，但要小心！你的對手可以搶奪你的最上層資產，除非你能成功守護（罩得住）它。'),
	 ('嗒寶-寶可夢 (Dobble Pokemon)','10-15 min','6+','2-8 人',NULL,'經典嗒寶玩法結合寶可夢元素。任何兩張卡片上都一定有一個相同的圖案（如皮卡丘），誰先喊出名字並搶到牌就得分。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('小惡魔 (Diavolo)','15-20 min','9+','2-6 人',NULL,'當骰子擲出後，玩家需快速判斷哪種顏色的小惡魔贏了（根據大小或奇偶），並搶奪桌上的對應模型，慢的人會損失靈魂。'),
	 ('誰是牛頭王 (6 Nimmt!)','30-45 min','9+','2-10 人',NULL,'玩家同時出一張牌，按規則排入桌上的四行牌中。若你的牌是該行的第六張，你就必須收回整行並獲得負分（牛頭）。'),
	 ('豆腐王國 (Tofu Kingdom)','15 min','9+','3-8 人',NULL,'豆腐王國的王子想找公主。有人會說真話、有人會說謊、有人會亂說話。王子必須從問答中判斷誰才是他的真愛。'),
	 ('知識線-動物篇 (Cardline: Animals)','15-25 min','6+','2-8 人',NULL,'將動物依照體型大小、體重或壽命進行排序。是一款寓教於樂，讓玩家在遊戲中認識自然常識的作品。'),
	 ('字字轉機-臉紅心跳 (Anomia: After Dark)','20-30 min','18+','3-6 人',NULL,'《字字轉機》的深夜版，類別卡全部替換為成人、不雅或具挑逗性的詞彙，僅限成人在聚會中大聊特聊。'),
	 ('字字轉機-圖像版 (Anomia Kids/Picture)','20 min','6+','3-6 人',NULL,'去除了文字標記，改用更直觀的圖案。即便年紀較小或還不識字的小朋友也能享受搶答與聯想的樂趣。'),
	 ('亡者神抽 (Dead Man''s Draw)','15-20 min','9+','2-4 人',NULL,'海盜主題的試手氣遊戲。一張接一張地抽牌，抽得越多獎勵越多，但一旦抽到重複的花色，當前回合的所有收穫都會化為烏有。'),
	 ('PAPAYOO','30 min','6+','3-8 人',NULL,'一種特殊的吃墩遊戲（Trick-taking）。玩家要避開收集到 Papayoo 卡和 7 號卡，因為這些卡片會帶來高額的扣分。'),
	 ('黃瓜五兄弟 (5 Cucumbers)','20 min','9+','2-6 人',NULL,'由大師 Friedemann Friese 設計。規則很簡單：不要贏得最後一墩！玩家要設法保留小牌到最後，否則會被迫吃下大量的黃瓜扣分。'),
	 ('變色龍 (Coloretto)','20-30 min','9+','2-5 人',NULL,'經典的收集遊戲。你可以收集多種顏色的變色龍，但只有三種顏色能加分，第四種開始會扣分。考驗你何時該收手，何時該塞爛牌給對手。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('洪水警報 (Land Under Water)','20-30 min','9+','3-5 人',NULL,'洪水來了！玩家要在每回合出牌爭奪救生圈，出最高或最低的人有不同的獎勵或懲罰。如果你的水位太高，就會溺水出局。'),
	 ('色字頭上一掌拍 (Color Smash)','10-15 min','6+','2-6 人',NULL,'眼明手快的反應遊戲。當卡片上的「文字顏色」與「文字內容」一致時，玩家要迅速拍擊牌堆。這是一款考驗大腦抗干擾能力的有趣作品。'),
	 ('心靈同步 (The Mind)','15-20 min','9+','2-4 人',NULL,'這不是普通的遊戲，這是一場心靈感應實驗。玩家不能說話或打信號，必須憑藉「感覺」依序打出手中 1-100 的數字卡片。'),
	 ('矮人礦坑 (Saboteur)','30-45 min','9+','3-10 人',NULL,'玩家分為好矮人與破壞者。好人要挖通隧道尋找黃金，破壞者則要隱藏身分並在關鍵時刻弄斷工具或封死道路。'),
	 ('力爭上游 (The Great Dalmuti)','30-60 min','9+','4-8 人',NULL,'《魔法風雲會》設計者的作品。玩家在每輪表現決定下一輪的階級（如大國王或卑微的小奴隸），奴隸必須上繳好牌給國王，非常現實又搞笑。'),
	 ('三國殺-國戰 (SanGuoSha: Kingdom Wars)','45-90 min','12+','2-12 人',NULL,'經典三國殺的變體規則。玩家一次操控兩名武將，並根據國籍（魏蜀吳群）結盟對抗。不到翻開武將的那一刻，沒人知道你是敵是友。'),
	 ('三國殺-標準 (SanGuoSha: Standard)','30-60 min','12+','2-10 人',NULL,'華人地區最受歡迎的陣營遊戲之一。分為主公、忠臣、反賊與內奸。透過技能與卡牌對抗，完成各自的勝利目標。'),
	 ('三國殺-鐵盒版','30-60 min','12+','3-10 人',NULL,'收錄了標準版內容並附帶精美鐵盒包裝，通常包含額外的擴充武將或配件，方便玩家攜帶出門開戰。'),
	 ('我滿懷業障的有病桌遊 (The Sick Game: Karma)','20-40 min','12+','2-6 人',NULL,'台灣知名團隊「有病制作」作品。充滿獨特的視覺風格與惡搞文本，玩家要透過丟擲業障來互相傷害，是一款節奏明快且風格強烈的派對遊戲。'),
	 ('我滿懷歧異的意識代碼 (The Sick Game: Code)','30-60 min','12+','1 人',NULL,'「有病制作」推出的解謎作品。玩家需根據書本或卡牌提供的線索進行邏輯推演，是一款適合靜下心來獨自挑戰的腦力作品。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('拼布藝術 (Patchwork)','15-30 min','9+','2 人',NULL,'極受好評的雙人策略遊戲。玩家要在 9x9 的布板上縫補布料，平衡時間成本與鈕扣資源，設法讓自己的拼布最完整且得分最高。'),
	 ('歡迎來到你的理想家園 (Welcome To...)','25 min','9+','1-100 人',NULL,'這是一場 1950 年代的建築競賽。玩家同時使用翻開的門牌號碼卡，在地圖紙上規劃街道、泳池與花園。理論上支援無限多人同時遊玩！'),
	 ('甜蜜的家 (Home Sweet Home)','15-20 min','6+','2-5 人',NULL,'溫馨可愛的小品遊戲。玩家要幫小動物們裝修新家，透過簡單的卡牌操作來完成家具配置，非常適合家長與幼齡孩子同樂。'),
	 ('捕蟲仔 (Bug Hunt)','15 min','6+','2-6 人',NULL,'考驗觀察力的速度遊戲。玩家要快速找出桌面上符合特定顏色、種類或特徵的蟲蟲。動作最快的人就是森林捕蟲王。'),
	 ('勝在有腦 (Cortex Challenge)','15-20 min','9+','2-6 人',NULL,'包含八種不同的挑戰：觸覺識圖、邏輯推演、迷宮追蹤、顏色辨識等，全面考驗玩家的大腦各區塊功能。'),
	 ('勝在有腦-兒童版 (Cortex Kids)','15 min','6+','2-6 人',NULL,'專為小朋友優化的挑戰題庫，保留了有趣的「觸覺卡」環節，讓孩子在遊戲中自然鍛鍊專注力與觀察力。'),
	 ('Magic School','10-15 min','6+','2-4 人',NULL,'由 Djeco 出品的精美小品。玩家需合作將魔法物品與對應的學徒進行配對，是一款充滿魔幻氛圍的記憶訓練遊戲。'),
	 ('海盜對決 (Pirate''s Duel)','10-15 min','6+','2 人',NULL,'簡單卻不失深度的雙人博弈。玩家在狹窄的甲板上進退，利用手牌來發動攻擊或防禦，目標是將對手逼入死角。'),
	 ('圖騰快手 (Jungle Speed)','15-20 min','6+','2-10 人',NULL,'當場上出現相同圖案時，玩家要立刻搶奪桌子中央的木製圖騰。這是一款賭上友情與指甲長度的極限反應遊戲。'),
	 ('SPYFALL (間諜危機)','15 min','12+','3-8 人',NULL,'除了間諜，所有人都知道身處的地點（如：太空站）。大家透過問答排除嫌疑，間諜則要試著套出地點資訊並隱藏身分。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('SPYFALL 2 (間諜危機 2)','15 min','12+','3-12 人',NULL,'經典間諜危機的續集。增加了更多有趣的地點，並支援更多玩家，甚至可能出現兩名分屬不同陣營的間諜互鬥。'),
	 ('卡卡頌-大全擴 (Carcassonne Big Box)','45-90 min','9+','2-6 人',NULL,'世界級經典遊戲。玩家透過拼放版圖來建設城堡、道路與草地，並派遣手下（米寶）占領資源以獲取積分。'),
	 ('山中小屋 (Betrayal at House on the Hill)','60-90 min','12+','3-6 人',NULL,'典型的恐怖電影開場。玩家探索鬼屋，直到某個時刻觸發「作祟」，其中一人將變成叛徒，與剩餘玩家展開生死對決。'),
	 ('山中小屋-寡婦行擴充 (Widow''s Walk)','60-90 min','12+','3-6 人',NULL,'為《山中小屋》增加了 20 個新房間與 50 個全新的劇本，讓玩家探索鬼屋的高度與廣度更上一層樓。'),
	 ('波多黎各 (Puerto Rico)','90-120 min','12+','2-5 人',NULL,'策略遊戲的巔峰之作。玩家扮演殖民時期的總督，透過建設、開墾與貿易來獲取財富與名聲，機制嚴謹且幾乎沒有運氣成分。'),
	 ('大創造時代 (Age of Innovation)','120-150 min','15+','1-5 人',NULL,'《神祕大地》系列的進化版。玩家操控不同的種族在版圖上擴張领土、升級建築，是一款極具深度的硬核策略遊戲。'),
	 ('街口/骰子街 (Machi Koro)','30 min','6+','2-4 人',NULL,'玩家透過擲骰觸發建築效果來賺錢。是一款風格清新、節奏明快的城鎮建設遊戲，非常適合推坑新手。'),
	 ('街口-百萬富翁擴充 (Machi Koro: Millionaire''s Row)','30-45 min','6+','2-4 人',NULL,'增加了更多高收益但也更具風險的建築卡片，讓《骰子街》的經濟競爭變得更加激烈與多變。'),
	 ('街口-港口擴充 (Machi Koro: Harbor)','45 min','6+','2-5 人',NULL,'引入了海洋與港口的概念，增加了新的大型地標，並支援第 5 位玩家加入遊戲。'),
	 ('街口-傳承 (Machi Koro Legacy)','30-45 min','9+','2-4 人',NULL,'共有 10 個章節。玩家的選擇會永久改變遊戲規則與配件，隨著故事推進，你的城鎮將演變成獨一無二的模樣。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('小島 (Tiny Islands)','20 min','9+','1-100 人',NULL,'玩家在自己的地圖紙上繪製各種地形。透過簡單的規則進行空間規劃，是一款適合多人同時遊玩且節奏輕快的作品。'),
	 ('江戶職人物語 (Iki)','60-90 min','12+','2-4 人',NULL,'玩家回到江戶時代的市井。透過僱傭職人與經營攤位來獲取「生之意義」（IKI），畫風精美且極具歷史韻味。'),
	 ('光合作用 (Photosynthesis)','45-60 min','9+','2-4 人',NULL,'這是一場森林中的光影博弈。玩家要控制樹木生長，利用太陽的方位來收集能量，同時設法用樹蔭遮擋對手的陽光。'),
	 ('星球 (Planet)','30-45 min','9+','2-4 人',NULL,'每個玩家手握一顆立體磁性星球。你需要將生態板塊貼在星球表面，以吸引各種動物前來棲息，配件極具手感與質感。'),
	 ('矩陣密室-25 (Room 25)','30-60 min','9+','1-6 人',NULL,'致敬電影《異次元殺陣》。玩家身處充滿機關的密室，需合作（或內鬥）找出出口。遊戲提供多種模式，包含叛徒模式與純合作模式。'),
	 ('12支流 (12 Rivers)','45 min','9+','2-4 人',NULL,'利用真實的重力感應與物理配件，玩家要引導河水中的珠子流向自己的領地，是一款視覺與遊戲性兼具的獨特作品。'),
	 ('妙筆神猜 (Pictomania)','20-30 min','9+','3-6 人',NULL,'由《歷史長河》大師設計。玩家要一邊畫自己的題目，一邊猜別人在畫什麼。畫得好不如畫得快，是一款手忙腳亂的派對遊戲。'),
	 ('巫術學院 (Potion Explosion)','30-45 min','9+','2-4 人',NULL,'桌遊版的「消消樂」。玩家從特製容器中取出彩色珠子（藥材），若觸發同色碰撞則可產生連鎖反應獲取更多資源，用來調配強大的藥水。'),
	 ('方舟動物園 (Ark Nova)','90-150 min','15+','1-4 人',NULL,'規劃並建立一個現代化的科學動物園。玩家需管理建設、飼養動物並支持全球保育計畫，是近年全球排名極高的策略神作。'),
	 ('方舟動物園-海洋世界擴充 (Ark Nova: Marine Worlds)','90-150 min','15+','1-4 人',NULL,'為本傳增加了水族館建築與海洋生物卡牌，引入了全新的特殊卡牌與更靈活的行動輪抽機制。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('維京．襲來 (Vikings Gone Wild)','45-90 min','9+','2-4 人',NULL,'玩家扮演維京首領，透過牌組構建來擴建村莊、招募戰士並攻擊對手，節奏明快且具有豐富的連擊感。'),
	 ('青蛙騎士 (Frogrider)','20-30 min','9+','2-4 人',NULL,'類似西洋跳棋的機制，玩家控制青蛙騎士在葉片間跳躍捕捉對手。不同的青蛙顏色對應不同的得分目標。'),
	 ('卡坦島 (Catan)','60-90 min','9+','3-4 人',NULL,'桌遊界的長青樹。玩家在島上收集資源、建設道路與城鎮，核心在於玩家間的資源交換與發展規劃。'),
	 ('卡坦島-騎士擴充 (Catan: Cities & Knights)','90-120 min','12+','3-4 人',NULL,'卡坦島最經典的進階擴充。玩家需訓練騎士抵禦蠻族入侵，同時發展城市商品來解鎖更強的科技。'),
	 ('卡坦島-5-6人騎士擴充','120-150 min','12+','5-6 人',NULL,'讓騎士擴充支援至 6 人遊玩，增加了遊戲的複雜度與競爭深度。'),
	 ('卡坦島-海洋擴充 (Catan: Seafarers)','90 min','9+','3-4 人',NULL,'玩家可以建造船隻前往島嶼之外的領土，增加了探索海洋與發現新資源的樂趣。'),
	 ('地城勇士 (Dungeon Fighter)','45-60 min','9+','1-6 人',NULL,'挑戰「投擲技巧」的合作遊戲。玩家要用各種奇葩姿勢（如：背對、彈跳）把骰子彈入標靶中來攻擊怪物。'),
	 ('一網打盡 (Catch the Fish)','20 min','6+','3-5 人',NULL,'簡單的卡牌遊戲，玩家要在適當的時機出牌來捕捉大魚，同時避免被對手的特殊卡牌反制。'),
	 ('猜心俱樂部 (Compatibility)','30-45 min','9+','3-8 人',NULL,'考驗玩家間的默契。每個人拿出一張圖片來對應題目，若你與隊友選到相同聯想的圖片即可得分。'),
	 ('搖滾巨塔 (Rock the Beat / We Will Rock You)','10-20 min','9+','2-6 人',NULL,'拍打大腿發出節奏，玩家要輪流打出自己的手勢並呼喚他人的手勢，極具挑戰性與爆笑效果。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('極限一發 (Bang!)','20-30 min','9+','2-4 人',NULL,'西部牛仔背景。玩家要利用卡牌攻擊、躲閃並使用特殊能力，設法成為最後的倖存者。'),
	 ('討拍小怪獸','15 min','6+','2-4 人',NULL,'可愛的小品遊戲。玩家要快速找出符合條件的小怪獸，適合家庭家長與小朋友互動。'),
	 ('土狼在笑你 (Coyote)','20-30 min','9+','3-6 人',NULL,'你看得到別人的數字卻看不到自己的。玩家需喊出所有人數字總和，並設法讓下家喊過頭。'),
	 ('飛躍魔盜團 (Magic Maze)','15 min','9+','1-8 人',NULL,'所有人不能說話！玩家各自控制一個行動方向，需默契配合引導四個英雄洗劫商場並逃脫。'),
	 ('獨家暗語 (Just One)','20 min','9+','3-7 人',NULL,'玩家需寫下一個詞來提示隊友猜題，但如果兩人寫了相同的詞，該線索就會作廢。'),
	 ('精靈捕手 (Magic School)','15 min','6+','2-4 人',NULL,'玩家需合作將魔法物品與對應的學徒進行配對，訓練孩子的短暫記憶與觀察力。'),
	 ('竹靈之道 (Bamboleo)','20 min','6+','2-4 人',NULL,'極致的平衡挑戰。玩家要從晃動的圓盤上取走積木，而不能讓圓盤翻倒。'),
	 ('推理事件簿 (Chronicles of Crime)','60-90 min','12+','1-4 人',NULL,'結合 APP 掃碼與 VR 技術，玩家扮演警探在犯罪現場調查物證、詢問證人以破案。'),
	 ('推理事件簿：月亮石的冒險','30-60 min','6+','1-100 人',NULL,'《推理事件簿》的兒童版。難度降低且主題奇幻，適合親子共同在平板與地圖上冒險。'),
	 ('爆炸小小兵 (Exploding Minions)','15-20 min','6+','2-5 人',NULL,'《爆炸貓》的聯名作。小小兵主題與特殊卡牌效果，帶給玩家搞笑又緊張的抽牌體驗。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('爆炸貓-天使與魔鬼 (Exploding Kittens: Good vs Evil)','15-20 min','6+','2-5 人',NULL,'爆炸貓系列作，增加了善惡對決機制與新的特殊卡牌，讓抽到爆炸卡後的博弈更為豐富。'),
	 ('狼來了！！ (Woooif!!)','20-30 min','9+','4-8 人',NULL,'這是一個關於農場保衛戰的陣營遊戲，玩家要隱藏自己的牧羊犬或狼的身分來贏得最終目標。'),
	 ('印加寶藏 (Incan Gold)','20-30 min','9+','3-8 人',NULL,'經典的「見好就收」遊戲。玩家深入神廟尋寶，決定繼續深入或帶著目前財寶逃走。'),
	 ('空中之城 (Celestia)','30 min','9+','2-6 人',NULL,'玩家共乘一艘飛船。船長要應對各種障礙，乘客則要猜測船長是否有足夠手牌通過，或決定跳船下機得分。'),
	 ('蝴蝶飛呀 (PAPILLONS)','20 min','6+','2-4 人',NULL,'溫馨的家庭遊戲。玩家在花園中放置板塊，吸引不同種類的蝴蝶並收集分數。'),
	 ('七大奇蹟 (7 Wonders)','30-45 min','9+','3-7 人',NULL,'玩家透過傳牌來建設文明的資源、軍事、科技或奇觀。特色是支援人數多且節奏緊湊。'),
	 ('七大奇蹟-對決 (7 Wonders Duel)','30 min','9+','2 人',NULL,'公認最強的雙人桌遊之一。保留了文明建設感，並增加了軍事壓制與科技獲勝的機制。'),
	 ('三人成築 (Team3)','10-15 min','9+','3-3 人',NULL,'三人合作遊戲：一人不能說、一人不能看、一人不能動。透過指令傳遞來完成積木建築任務。'),
	 ('凱爾特之森','30-45 min','9+','2-5 人',NULL,'在古老的凱爾特森林中探索。玩家要規劃領地並與他人競爭珍貴的資源。'),
	 ('種豆 (Bohnanza)','45 min','9+','2-7 人',NULL,'不能調整手牌順序！你必須透過與對手交換、贈送豆子來清出手中的牌位，是一款強調口才的經典遊戲。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('奶酪大盜 (Cheese Thief)','15 min','9+','4-8 人',NULL,'極速陣營遊戲。大盜偷了奶酪，其他小老鼠要在有限的「天黑時間」與討論中抓出真兇。'),
	 ('星杯傳說 (Asterisk Cup)','45-60 min','12+','4-6 人',NULL,'類似 MOBA 遊戲的桌遊。玩家組隊選擇不同技能的角色，透過手牌與技能連動攻擊對手陣營。'),
	 ('造王者 (King Maker)','45-90 min','12+','3-6 人',NULL,'玩家扮演權臣。你的目標不是當王，而是扶植或破壞特定的候選人來獲得最終勝利。'),
	 ('內鬼疑雲 (The Insider)','15 min','9+','4-10 人',NULL,'所有人在猜題，但其中一個內鬼知道答案。內鬼要引導大家猜中，又不能被識破自己知道答案。'),
	 ('暗影獵人 (Shadow Hunters)','45-60 min','9+','4-8 人',NULL,'分為獵人、暗影與中立陣營。透過探索與道具來確認他人身分並發起戰鬥。'),
	 ('閃靈快手 (Ghost Blitz)','15 min','6+','2-8 人',NULL,'根據卡片指示快速搶奪桌上模型，考驗腦神經對顏色與形狀的反應速度。'),
	 ('閃靈快手-2.0 (Ghost Blitz 2.0)','15 min','6+','2-8 人',NULL,'增加了新的物品模型與稍微變化的規則，與 1.0 混合遊玩會更加困難刺激。'),
	 ('閃靈快手-3.0 (Ghost Blitz 5 to 12)','15 min','9+','2-8 人',NULL,'模型增加到 9 個！難度大幅提升，是閃靈系列中最高階的反應挑戰。'),
	 ('風聲-黑名單 (The Message)','30-60 min','12+','3-9 人',NULL,'特工諜戰主題。玩家分為軍統、潛伏與打醬油陣營，透過傳遞真假情報來達成勝利。'),
	 ('忍者之夜 (Night of the Ninja)','20-30 min','9+','4-11 人',NULL,'快速、混亂的陣營對決。玩家輪抽角色牌來發動效果，設法殺掉敵對陣營的成員。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('炸彈 BOOM (Time Bomb)','15-30 min','9+','2-12 人',NULL,'分為特警與恐怖分子。特警要剪斷所有導線，恐怖分子則要引導特警剪到炸彈。'),
	 ('寶石獵人 (Gem Heist)','30 min','9+','3-6 人',NULL,'玩家在博物館中爭奪最珍貴的寶石，需考慮如何躲避警報與對手的陷害。'),
	 ('阿瓦隆 (Avalon)','30-60 min','12+','5-10 人',NULL,'正義與邪惡的對決。不需淘汰玩家，全程透過投票、出任務與言語辯論來找出臥底。'),
	 ('火柴會說話 (Stick Stories)','30 min','9+','3-8 人',NULL,'利用簡單的火柴棍、透明卡片等配件組合成聯想圖案，讓隊友猜出題目。'),
	 ('揮霍有度 (High Society)','20 min','9+','3-5 人',NULL,'競標珍貴物品。但最殘酷的規則是：遊戲結束時錢最少的人直接判輸，再多高分也沒用。'),
	 ('機密代號 (Codenames)','15-20 min','9+','2-8 人',NULL,'隊長給出一個詞來提示隊員找出己方特務，需避開暗殺者，是極受好評的語言邏輯遊戲。'),
	 ('機密代號-有圖有真相 (Codenames: Pictures)','15-20 min','9+','2-8 人',NULL,'將文字換成充滿奇幻風格的圖片。隊長需用一個詞聯結多張圖片，隊員則要避開對方的特務與致命的暗殺者。'),
	 ('機密代號-裡應外合 (Codenames: Duet)','15-30 min','12+','2 人',NULL,'專為兩人設計的合作版本。兩位玩家共享一張任務卡的正反兩面，必須在有限的回合內互相提示，找出所有己方特務。'),
	 ('皮卡丘樹 (Pikachu Tree)','10-20 min','6+','1-100 人',NULL,'考驗手部穩定的平衡遊戲。玩家輪流將皮卡丘掛在晃動的樹枝上，弄倒的人即出局。因機制簡單，理論上可支援極多人輪流參與。'),
	 ('截碼戰-5週年記念版 (Decrypto)','30 min','12+','3-8 人',NULL,'兩隊互相破解對方的數字代碼。你既要讓隊友聽懂提示，又要防止對手截獲資訊，是目前評價極高的語言邏輯派對遊戲。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('截碼戰-光碟擴充 (Decrypto: Laserdrive)','30-45 min','12+','3-8 人',NULL,'為截碼戰增加了「類別卡」。如果提示詞符合類別，可以獲得額外獎勵，增加了出題的限制與挑戰性。'),
	 ('反斗馬戲團 (Circus Flohcati)','15-20 min','9+','2-4 人',NULL,'經典的收集遊戲。玩家翻開馬戲團卡，決定要冒險多翻一張或見好就收。收集不同類型的表演來獲取高分。'),
	 ('摺足先登 (Fold-it)','15-20 min','9+','1-5 人',NULL,'玩家每人有一張特製手帕，需根據題目卡快速摺疊手帕，使指定料理完整露出。考驗空間想像力與手速。'),
	 ('芋頭天堂 (Taro Paradise)','20-30 min','9+','2-6 人',NULL,'以台灣在地元素為靈感的卡牌遊戲。玩家透過出牌組合與特殊效果，在歡樂的氛圍中角逐分數。'),
	 ('小魚大歷險 (Fish Eat Fish)','15-20 min','6+','2-4 人',NULL,'大魚吃小魚的簡單博弈。玩家要讓自己的小魚在海底生存並吃掉更小的魚來變強，適合親子同樂。'),
	 ('狼人殺大盒版 (The Village)','30-90 min','12+','8-29 人',NULL,'收錄了大量特殊角色（如白狼王、守衛等）。玩家分為狼人與村民陣營，透過日間討論與夜間行動來決定村莊的生死。'),
	 ('狼人殺-魔幻科技 (Werewolf: Tech)','30-60 min','12+','7-12 人','bg_1774760390418.jpeg','狼人殺的特殊主題版。加入了更具未來感的角色設定與特殊技能，讓傳統的推坑過程更具變數。'),
	 ('洞洞方塊 (Puncto)','15-20 min','9+','2-2 人',NULL,'抽象策略遊戲。玩家要在重疊的方塊中尋找連線機會，考驗對空間結構的觀察力與阻擋對手的能力。'),
	 ('13道線索 (13 Clues)','30 min','9+','2-6 人',NULL,'每人看得到別人的線索卻看不到自己的。透過向他人提問（如：你看到幾張紫色的卡？），推敲出自己面前的真相。'),
	 ('連線計畫 (SET UP)','20-30 min','9+','2-4 人',NULL,'玩家在版圖上放置方塊進行同色或同數字的連線。簡單好上手的抽象遊戲，老少咸宜。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('畫中有？ (Picture It!)','20 min','9+','3-6 人',NULL,'玩家要根據局部線索或提示進行作畫，並讓他人猜測畫中內容，是一款充滿創意的派對遊戲。'),
	 ('骰子街 (Machi Koro)','30 min','9+','2-4 人',NULL,'玩家透過擲骰子獲取金幣，購買不同建築。建築會在特定點數觸發效果，目標是先蓋完所有地標建築。'),
	 ('骰子街-百萬富翁擴充','30-45 min','9+','2-4 人',NULL,'增加了更多高報酬與特殊功能的建築，讓建設路徑更加豐富，賺錢的速度也隨之飆升。'),
	 ('骰子街-港口擴充','30-45 min','9+','2-4 人',NULL,'引入了港口與漁船機制。增加了更複雜的資源連動，且支援最多 5 人遊玩（視版本而定）。'),
	 ('拔毛運動會 (Zicke Zacke Hühnerkacke)','15-20 min','0+','2-4 人',NULL,'超經典記憶遊戲。翻開中央圖案與腳下相同即可前進，若超車還能拔掉對手屁股上的羽毛。'),
	 ('步步高升 (Ladder 29)','20-30 min','9+','2-4 人',NULL,'類似大老二的機制，玩家需根據任務卡的要求出牌，先將手牌出完或達成特定目標者獲勝。'),
	 ('花磚物語 (Azul)','30-45 min','9+','2-4 人',NULL,'鋪設皇宮牆面。玩家輪流從工坊拿取瓷磚，需精算剩餘空間與顏色分配，避免因溢出而大幅扣分。'),
	 ('花磚物語-馬賽克水晶擴充','30-45 min','9+','2-4 人',NULL,'提供了塑膠凹槽版圖，解決磁磚容易位移的問題，並增加了新的得分計分板增加挑戰。'),
	 ('花磚物語-夏日行宮 (Azul: Summer Pavilion)','30-45 min','9+','2-4 人',NULL,'花磚系列第三作。引入菱形瓷磚與百搭色，玩家可保留磁磚至下回合使用，策略彈性與規劃感更高。'),
	 ('香料之路 大盒版 (Century: Golem Big Box)','30-60 min','9+','2-4 人',NULL,'建立高效的資源轉換生產線（如：黃寶石換紅寶石）。大盒版收錄多個小擴充，配件質感極佳。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('貴婦的遺產 (Ladies & Gentlemen)','30 min','9+','2-5 人',NULL,'分組進行。紳士們在市場上賺錢，女士們則負責購物比美。是一款充滿反諷與趣味互動的派對遊戲。'),
	 ('璀璨寶石 (Splendor)','30 min','9+','2-4 人',NULL,'收集寶石Token來購買卡片。卡片提供的永久資源能讓你買到更昂貴的卡，進而吸引貴族來訪獲取 15 分勝利。'),
	 ('璀璨寶石-城市擴充 (Splendor: Cities)','30-40 min','9+','2-4 人',NULL,'包含四個不同模組。改變了原本 15 分的結束條件，增加了城市封印、城堡機制與新的發展卡。'),
	 ('璀璨寶石-漫威版 (Splendor Marvel)','30 min','9+','2-4 人',NULL,'加入了「無限寶石」與「復仇者集結」標誌。需收集齊所有顏色且擁有一定戰力才能奪取無限手套獲勝。'),
	 ('璀璨寶石-寶可夢版 (Splendor Pokemon)','30 min','9+','2-4 人',NULL,'核心不變，但加入進化機制。透過精靈球購買低階寶可夢並進化，帶入感極強，是目前最受歡迎的聯名款。'),
	 ('璀璨寶石-雙人版 (Splendor Duel)','20-30 min','9+','2-2 人',NULL,'從 5x5 的版圖中相連取得寶石。增加了珍珠資源、特殊技能與三種獲勝途徑，是目前最強的雙人策略小品。'),
	 ('失落的城市 (Lost Cities)','20-30 min','9+','2-2 人',NULL,'玩家在五條探險路徑上放置數字卡。若路徑分數不夠會倒扣，考驗何時打出投資卡與何時放棄跟進的心理戰。'),
	 ('幽靈大冒險 (Ghost Adventure)','20 min','9+','1-4 人',NULL,'使用發條陀螺在不同的立體地圖上移動。玩家需傾斜地圖讓陀螺轉到指定地點，是非常新穎的合作體感遊戲。'),
	 ('青青珊瑚島 (Blue Lagoon)','30-45 min','9+','2-4 人',NULL,'玩家在群島上建立定居點。分成兩個階段：探索與定居。需競爭稀有資源並規劃最強的連線路徑。'),
	 ('說夢人 (When I Dream)','20-30 min','9+','4-10 人',NULL,'一名玩家戴眼罩聽提示猜詞。有人會給真提示（小精靈），有人會給假提示（食夢魔），過程充滿干擾與樂趣。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('名偵大賽 (Detective Club)','30-45 min','9+','1-8 人',NULL,'大家根據謎底詞打出兩張相似圖卡，但有一人（臥底）不知道詞，只能跟風出牌。最後大家要揪出那個不知所云的人。'),
	 ('走私 MEXICO','30 min','9+','3-5 人',NULL,'玩家扮演走私客，設法將貨物帶過邊境。需面對檢查員的盤查，考驗玩家的表情管理與唬爛技巧。'),
	 ('現代藝術 (Modern Art)','45-60 min','9+','3-5 人',NULL,'拍賣界神作。玩家買賣五位畫家的畫作，畫作價值由受歡迎程度決定。需精準估價並在市場過熱前獲利了結。'),
	 ('數字九層塔 (NMBR9)','20 min','9+','1-4 人',NULL,'拼放數字版塊。層數越高，數字分數加倍越多。需在第一層打好寬廣地基，才能向上疊出高分。'),
	 ('賽馬大亨 (Winner''s Circle)','45 min','9+','2-9 人',NULL,'經典的賽馬遊戲。觀察每隻馬的數據進行下注，並透過擲骰控制馬匹前進。充滿了控制他人愛馬與讓對手慘賠的樂趣。'),
	 ('彈彈棋 (Crokinole)','15 min','9+','2-2 人',NULL,'在圓形木質版上彈射圓盤，設法進入中心高分區或將對手撞出。是極具觀賞性與手感的傳統競技遊戲。'),
	 ('步步高升：機智疊塔 (Upwards)','20-30 min','9+','1-4 人',NULL,'透過堆疊方塊與規劃結構來獲勝。是一款結合了物理穩定性與邏輯預判的小品佳作。'),
	 ('新演化論 (Evolution: New World)','60 min','12+','2-5 人',NULL,'創造生物並添加特徵（如肉食、偽裝）。在食物有限的環境中競爭生存，生物會因特徵組合產生多樣的生態聯動。'),
	 ('新演化論-氣候與飛行擴充','60-90 min','12+','2-5 人',NULL,'加入了極端氣候變化與飛行特徵。生物必須應對寒流或熱浪，並利用領空獲取更多生存空間。'),
	 ('新演化論-海洋擴充','60-90 min','12+','2-5 人',NULL,'將演化戰場帶到深海。增加了巨大的海洋物種與全新的覓食機制，增加了遊戲的策略寬度。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('新演化論-起源 (Evolution: Origin)','45 min','9+','2-5 人',NULL,'簡化了規則與複雜度。保留了演化核心樂趣，適合初次接觸演化系列的玩家或家庭遊玩。'),
	 ('三奧米諾 (Triominoes)','20 min','6+','2-4 人',NULL,'三角形版的骨牌遊戲。玩家需匹配三角形的三個邊界數字來放置，考驗數字感與幾何排列能力。'),
	 ('綿羊爭牧場 (Battle Sheep)','15 min','6+','2-4 人',NULL,'玩家在版圖上分割自己的羊群，設法佔領最多的草地並堵死對手。規則極簡，但博弈感極強。'),
	 ('二人三築 (Lift it!)','30 min','9+','1-8 人',NULL,'玩家頭戴吊鉤，兩人一組合作「釣」起建築方塊。非常滑稽且考驗身體控制力與默契。'),
	 ('四季 (Seasons)','45-60 min','15+','2-4 人',NULL,'透過骰子收集能量並打出魔法物品。需在三年的季節循環中規劃資源轉換，美術風格極其精美且卡牌互動強烈。'),
	 ('巫師之石 (Witchstone)','60-90 min','12+','2-4 人',NULL,'玩家在煉金釜中放置板塊，觸發一系列華麗的行動連鎖。是近期極受推崇的連擊式中度策略遊戲。'),
	 ('馬尼拉 (Manila)','60 min','9+','3-5 人',NULL,'經典的黑市貿易遊戲。玩家在黑市中賭哪艘船會安全抵達港口，哪艘會翻船。考驗機率計算與大膽下注的勇氣。'),
	 ('村莊 (Village)','60-90 min','12+','2-4 人',NULL,'獨特的「時間管理」機制。玩家控制家族成員在村莊中工作、參政或旅行，成員會隨著時間老化死亡，如何讓後代在村莊誌留下名聲是獲勝關鍵。'),
	 ('豐饒大地 (Fertility)','30-45 min','9+','2-4 人',NULL,'古埃及背景的板塊放置遊戲。玩家要在尼羅河谷開墾土地並建造紀念碑，透過巧妙的資源連結來獲得最大收益。'),
	 ('文明繪卷 (Tapestry)','90-120 min','12+','1-5 人',NULL,'在4條發展軌上推進。遊戲包含大量精美的建築模型，讓玩家親手繪製出從石器時代到近未來的文明史詩。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('龍城對壘 (Dragon Castle)','30-45 min','9+','2-4 人',NULL,'受到麻將靈感啟發的遊戲。玩家從逐漸崩塌的龍城中拆取牌塊，並在自己的板塊上重新構建堡壘與祭壇。'),
	 ('騎士紋章 (Barony)','45 min','9+','2-4 人',NULL,'玩家扮演男爵擴張領地。規則高度抽象且嚴謹，沒有任何隨機要素，完全考驗玩家的佈局與封鎖能力。'),
	 ('拯救北極熊 (Rescue Polar Bears: Data and Temperature)','30-60 min','9+','1-4 人',NULL,'玩家扮演科學組織成員，在冰層融化前搶救北極熊。遊戲具備強烈的環保意識，配件精美且富有教育意義。'),
	 ('我的村莊 (My Village)','60-90 min','12+','2-4 人',NULL,'《村莊》系列的獨立作品。將核心機制改為骰子驅動，玩家依然要經歷生死循環，但策略重心轉移到了骰子點數的分配。'),
	 ('拉密 (Rummikub)','20-40 min','6+','2-4 人','bg_1774760294253.jpeg','俗稱「德國麻將」。玩家需觀察場上的數字組合，進行拆解與重組，將手中的牌全部出完。是訓練邏輯與專注力的世界級經典。'),
	 ('拉密-變臉 (Rummikub With A Twist)','20-40 min','6+','2-4 人',NULL,'拉密的進階版。加入了多種特殊的「百搭牌」（如變色、雙人百搭），讓重組過程更加燒腦多變。'),
	 ('台北大空襲 (Raid on Taihoku)','45-60 min','12+','2-4 人',NULL,'背景設定在二戰末期的台北。玩家扮演家中的不同成員，在空襲威脅下努力求生。具備強烈的沉浸感與感人的歷史背景。'),
	 ('地產大亨-瑪莉歐 (Monopoly: Super Mario)','45-60 min','9+','2-6 人',NULL,'經典地產大亨規則結合任天堂瑪莉歐元素，包含角色技能、金幣代替紙鈔以及經典音效配件。'),
	 ('地產大亨-航海王 (Monopoly: One Piece)','45-60 min','9+','2-6 人',NULL,'航海王聯名款。玩家要在版圖上招募船員並爭奪領地，卡牌皆換成動漫中的經典台詞與事件。'),
	 ('地產大亨-七龍珠 (Monopoly: Dragon Ball Z)','45-60 min','9+','2-6 人',NULL,'七龍珠Z主題。以戰鬥力與賽亞人星球作為房地產標的，適合龍珠粉絲收藏與遊玩。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('蒼天之死 (The Death of Blue Sky)','30-60 min','12+','4-6 人',NULL,'以黃巾之亂為背景。玩家身分在朝廷與叛軍間擺盪，需在亂世中看準時機站隊或反戈一擊。'),
	 ('地產大亨-美少女戰士 (Monopoly: Sailor Moon)','45-60 min','9+','2-6 人',NULL,'美少女戰士聯名款。精美的棋子與插圖設計，將經典房地產玩法帶入魔法少女的世界。'),
	 ('我是大老闆 (I''m the Boss!)','60 min','12+','3-6 人',NULL,'談判類桌遊代表。玩家必須透過嘴砲與利益交換來促成交易。隨時可能被對手插手搶走主導權，過程充滿爾語我詐。'),
	 ('鍛骰物語 (Dice Forge)','45 min','9+','2-4 人',NULL,'實體改造骰子的創新玩法。玩家可以購買更強的骰面零件換到骰子上，透過自製的強大骰子來贏得神的挑戰。'),
	 ('逃離亞特蘭提斯 (Survive: Escape from Atlantis!)','45-60 min','9+','2-6 人',NULL,'小島正在沉沒！玩家要救出自己的村民，同時控制海怪去吃掉別人的村民。是一款「友情破壞」傾向強烈的歡樂遊戲。'),
	 ('展翅翱翔 (Wingspan)','40-70 min','9+','1-5 人',NULL,'紅遍全球的鳥類主題遊戲。經營保護區、收集飼料與鳥蛋，畫風極其精美，卡牌能力設計高度還原鳥類習性。'),
	 ('皇輿爭霸 (Dominion)','30 min','9+','2-4 人',NULL,'牌組構建遊戲鼻祖。玩家從公共牌堆購買行動卡來優化自己的牌組，如何平衡產錢與得分速度是核心智慧。'),
	 ('碰撞機器人 (Ricochet Robots)','30 min','9+','1-100 人',NULL,'純粹的空間解謎競賽。所有人同時思考如何用最少步數將機器人彈射到目標點，理論上支援無限多人同時思考。'),
	 ('駱駝大賽 (Camel Up)','30 min','9+','3-8 人',NULL,'荒謬又刺激的沙漠競賽。駱駝會互相騎乘前進，玩家要下注獲勝或墊底的駱駝，運氣與笑點十足。'),
	 ('馬王爭霸 (Long Shot)','45-60 min','9+','3-8 人',NULL,'賽馬博弈遊戲。玩家除了下注，還能購買馬匹、發動特殊能力來干擾賽果，比《駱駝大賽》更具策略深度。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('雨後新香 (Petrichor)','60-90 min','9+','1-5 人',NULL,'玩家扮演雲朵。透過降雨來灌溉植物，並在不同作物的生長區域中競爭分數，美術風格極其詩意。'),
	 ('森生不息 (Living Forest)','45 min','9+','2-4 人',NULL,'玩家扮演自然之靈保護森林。透過三種不同的獲勝途徑（種樹、滅火、收集聖花）展現多樣的策略路徑。'),
	 ('一千零一夜 (Tales of the Arabian Nights)','120 min','12+','2-4 人',NULL,'這是一本「可以玩的書」。玩家在伊斯蘭世界冒險，透過對事件的選擇觸發數千種不同的故事結局，沉浸感極高。'),
	 ('聖托里尼 (Santorini)','20 min','9+','2-4 人',NULL,'極美的希臘建築桌遊。玩家移動工人並蓋房子，配合各種神祇的特殊能力，設法最先登上帝國頂端。'),
	 ('郎中闖江湖 (The Quacks of Quedlinburg)','45 min','9+','2-4 人',NULL,'煉金術士盲抽藥材放入鍋中。抽越多效果越強，但白藥粉超標會炸鍋！極具爽快感與風險管理的博弈遊戲。'),
	 ('殖民火星 (Terraforming Mars)','90-120 min','12+','1-5 人',NULL,'改造火星的溫度、氧氣與海洋。透過打出上百種計畫卡片建立優勢，是全球最熱門的策略神作之一。'),
	 ('道場 (Dojo Kun)','60-90 min','12+','1-4 人',NULL,'玩家經營武術道場。招募學生、擴建設施並參加武術大會，是一款主題性極強的工放遊戲。'),
	 ('奧爾良 (Orléans)','90 min','12+','2-4 人',NULL,'Bag Building 代表作。從布袋中抽取隨從來執行行動，透過不斷招募與優化隨從比例來擴大版圖優勢。'),
	 ('奧爾良-強敵入侵擴充 (Orléans: Invasion)','90-120 min','12+','1-5 人',NULL,'為奧爾良增加了合作模式、單人模式以及新的事件與配件，大幅提升了耐玩度。'),
	 ('龍年 (In the Year of the Dragon)','60-90 min','12+','2-5 人',NULL,'大師 Stefan Feld 作品。玩家要在災禍不斷的一年裡設法存活，極其考驗對未來回合的規劃與預判。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('枯山水 (Zen Garden/Karesansui)','60-90 min','9+','2-4 人',NULL,'扮演僧侶拼放砂石與石頭，追求最高的禪意藝術境界。配件質感極佳，充滿平靜中的競爭感。'),
	 ('亞魯特學院 (Anludim)','45-60 min','9+','2-4 人',NULL,'玩家扮演魔法學生，在學院中學習並調配藥水。是一款畫風柔和、機制穩定的輕中度策略遊戲。'),
	 ('密涅瓦 (MINERVA)','60-90 min','12+','1-4 人',NULL,'玩家扮演古羅馬執政官。透過建設神殿與城市設施來獲得勝利，考驗對建築連動與資源轉換的規劃。'),
	 ('水下城市 (Underwater Cities)','90-150 min','12+','1-4 人',NULL,'在深海建立生存圈。玩家需將卡牌顏色與行動格顏色對應以觸發最強效果，是深度與流暢度兼具的佳作。'),
	 ('馬可波羅 (The Voyages of Marco Polo)','60-90 min','12+','2-4 人',NULL,'重策神作。玩家扮演具備強大不平衡能力的旅行者，在歐亞大陸穿梭。骰子放置機制極具策略思考。'),
	 ('馬可波羅-擴充 (Marco Polo: New Characters)','60-90 min','12+','2-4 人',NULL,'增加了全新的角色技能與版圖配件，讓馬可波羅的變化性與重玩價值大幅增加。'),
	 ('馬可波羅-可汗的托付 (Marco Polo II: In the Service of the Khan)','60-100 min','12+','2-4 人',NULL,'馬可波羅的獨立續作。優化了資源流動與路線設計，被許多老玩家認為是比一代更平衡且豐富的究極版。'),
	 ('特魯瓦 (Troyes)','60-90 min','12+','2-4 人',NULL,'經典重策。特色是骰子視為勞動力且「可以購買別人的骰子」，需平衡應對災難與建設大教堂。'),
	 ('木鹿 (Merv: The Heart of the Silk Road)','60-90 min','15+','1-4 人',NULL,'在絲綢之路的核心城市中積累財富。遊戲版圖華麗，玩家需在防禦外敵與自身發展間取得極致平衡。'),
	 ('死亡寒冬 (Dead of Winter)','60-120 min','12+','2-5 人',NULL,'殭屍末日背景。每人都有個人目標且可能隱藏叛徒。充滿道德抉擇與精采故事事件的經典作品。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('追隨達爾文 (On the Origin of Species)','45-60 min','9+','2-5 人',NULL,'扮演科學家在加拉巴哥群島收集生物樣本。是一款科普色彩濃厚且機制洗鍊的策略遊戲。'),
	 ('終焉帝國 (Imperial Settlers: Empires of the North)','45-90 min','9+','2-4 人',NULL,'玩家扮演北方部族擴展疆域。不同部族有完全不同的牌組風格，畫風可愛但策略深度充足。'),
	 ('南河旅人 (Wayfarers of the South Tigris)','60-120 min','12+','1-4 人',NULL,'西王國系列團隊新作。在巴格達黃金時代探索星空與海洋，機制融合度極高，是硬核玩家首選。'),
	 ('奧爾良-瘟疫入侵擴充 (Orléans: Plague)','90-120 min','12+','2-5 人',NULL,'增加了瘟疫機制與新的玩家擋板，讓遊戲的資源管理變得更加緊迫且具有挑戰性。'),
	 ('新阿姆斯特丹 (Nieuw Amsterdam)','90-120 min','12+','2-5 人',NULL,'模擬 17 世紀荷蘭在美洲的殖民。結合了獨特的拍賣系統與資源分配，極具歷史厚重感。'),
	 ('拉斯維加斯 (Las Vegas Royale)','30 min','9+','2-8 人',NULL,'非常直觀的搶錢遊戲。玩家將骰子分配到不同賭場，規則極簡但過程熱血，適合跨年齡層遊玩。'),
	 ('女巫的佳釀 (Witch''s Brew)','45 min','9+','2-5 人',NULL,'經典的博弈心理戰。玩家要宣布自己的角色，若沒人敢挑戰你就能執行強大效果。是《波多黎各》設計師的小品傑作。'),
	 ('王國軼聞錄 (Paper Tales)','30-45 min','12+','2-5 人',NULL,'獨特的「老化」機制。玩家徵召士兵與建築，但每回合生物會獲得老化標記，最終死去。需在有限生命週期內發揮最大戰力。'),
	 ('斯凱島 (Isle of Skye)','45-60 min','9+','2-5 人',NULL,'玩家自己為手中的板塊定價，別人可以買走，若沒人買則自己花錢留著。結合了定價心理學與版圖建設的極佳作品。'),
	 ('御竹園 (Takenoko)','45 min','9+','2-4 人',NULL,'扮演日本園丁。玩家要種植竹子、灌溉土地，同時還要應對那隻會到處亂吃竹子的貪吃大貓熊。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('御竹園-熊孩子擴充 (Takenoko: Chibis)','45-60 min','9+','2-4 人',NULL,'加入了貓熊媽媽與可愛的熊寶寶。提供了新的土地板塊與更多樣化的得分目標卡。'),
	 ('伊斯坦堡 (Istanbul)','40-60 min','9+','2-5 人',NULL,'在大市集中奔走收集紅寶石。特色是移動後必須留下或接回助手，如何規劃出一條不回頭的循環路徑是獲勝核心。'),
	 ('頭等艙列車 (First Class)','40-80 min','9+','2-4 人',NULL,'《俄羅斯鐵路》的卡牌版。玩家經營東方快車，升級車廂並延伸鐵軌，透過模組組合，每一局都有不同的策略體驗。'),
	 ('權力遊戲 (A Game of Thrones: The Board Game)','120-180 min','15+','3-6 人',NULL,'忠實還原冰與火之歌的政治鬥爭。玩家秘密下達指令，在版圖上行軍、支援或背叛盟友，是一款史詩級的友情破壞遊戲。'),
	 ('塔樓 (Talo)','20-30 min','6+','2-4 人',NULL,'玩家需利用不同長度的積木搭梯向上。最先讓自己的小人爬到第十層的人獲勝，兼具邏輯思考與實體堆疊的樂趣。'),
	 ('蒙巴薩 (Mombasa)','75-150 min','12+','2-4 人',NULL,'經典重策。玩家在非洲大陸投資不同公司的股份。擁有創新的卡牌回收機制，策略深度極高。'),
	 ('石器時代-時尚擴充','60-100 min','9+','2-5 人',NULL,'增加了珠寶資源與裝飾機制，並讓遊戲人數支援到 5 人，提升了遊戲的精緻度與競爭空間。'),
	 ('英雄止步 (Keep the Heroes Out!)','40-90 min','9+','1-4 人',NULL,'玩家扮演地下城的怪物（如史萊姆、龍），合作守護寶藏，擊退前來冒險的討厭英雄們。畫風可愛但難度極高。'),
	 ('英雄止步-會長的復仇擴充','40-90 min','9+','1-4 人',NULL,'為英雄止步增加了新的怪物種類與英雄頭目，讓地下城的保衛戰更加白熱化。'),
	 ('英雄止步-偉大的沉睡者擴充','40-90 min','9+','1-4 人',NULL,'引入了克蘇魯主題的怪物與新的混亂機制，增加了遊戲的變化性。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('阿納克遺蹟 (Lost Ruins of Arnak)','60-120 min','12+','1-4 人',NULL,'玩家深入神秘島嶼探險。融合了資源收集、爬聖殿音軌與牌組強化，是近年最受推崇的全能型策略作品。'),
	 ('電力公司 (Power Grid)','90-120 min','12+','2-6 人','bg_1774760564809.jpeg','標售發電廠、購買燃料並建設城市供電網絡。需在資源價格波動與城市建設成本間取得平衡，是經濟類桌遊的巔峰。'),
	 ('電力公司-北歐地圖','90-120 min','12+','2-6 人',NULL,'北歐地圖針對特定的資源（如風力、核能）分布做了調整，帶來全新的佈局策略。'),
	 ('電力公司-英國地圖','90-120 min','12+','2-6 人',NULL,'英國與愛爾蘭地圖，由於地理隔離，玩家在電網連接上會面臨更嚴峻的空間挑戰。'),
	 ('電力公司-印度地圖','90-120 min','12+','2-6 人',NULL,'印度地圖模擬了高人口密度下的電力短缺壓力，資源搶奪感比原版更強烈。'),
	 ('閃燃瞬間 (Flash Point: Fire Rescue)','45 min','9+','2-6 人',NULL,'玩家扮演消防小組進入燃燒的房屋。需分工滅火與救出受困者，火勢會隨著隨機因素迅速蔓延，非常緊張刺激。'),
	 ('騎士學院 (Knights of the Round Table)','45-60 min','9+','2-5 人',NULL,'玩家扮演騎士學徒，透過訓練各種技能（如騎馬、格鬥）來參加錦標賽，爭奪成為圓桌武士的榮耀。'),
	 ('談鬼俱樂部 (Ghost Chat)','30 min','9+','3-5 人',NULL,'極具創意的台灣原創遊戲。玩家要在聊天中隱藏特定的靈異線索，或設法找出誰才是真正的鬼。'),
	 ('盆景大師 (Bonsai)','40 min','9+','1-4 人',NULL,'玩家在面前拼湊出屬於自己的盆栽景觀。需考慮樹木的生長方向與美學價值，是一款視覺感與遊戲性兼具的小品策略。'),
	 ('布魯日 (Brügge)','60-90 min','12+','2-4 人',NULL,'大師 Stefan Feld 作品。玩家在比利時布魯日競爭權力。每張卡牌都有多種用途，需在有限的回合內做出最優選擇。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('骰築英雄 (Roll Player)','60-90 min','9+','1-4 人',NULL,'這是一個「創造 RPG 角色」的遊戲。玩家透過擲骰與買裝備來填滿角色的力量、敏捷等數值，設法符合職業目標。'),
	 ('骰築英雄-怪獸與爪牙擴充','60-120 min','9+','1-4 人',NULL,'讓創造出來的角色有用武之地！增加了怪獸戰鬥階段，玩家可以帶著練好的英雄去狩獵大魔王。'),
	 ('鐵道任務 (Ticket to Ride)','30-60 min','9+','2-5 人',NULL,'收集同色火車卡來建設城市間的鐵路。規則極簡，但路線競爭激烈，是全球最受歡迎的入門策略遊戲之一。'),
	 ('夢想家園 (Dream Home)','30 min','6+','2-4 人',NULL,'玩家規劃並裝修自己的夢幻洋房。收集客廳、臥室或昂貴的頂樓裝飾，是一款視覺感非常療癒的家庭遊戲。'),
	 ('印加聖谷 (Urubamba Valley)','45-60 min','9+','2-5 人',NULL,'在古印加帝國中開發土地。透過耕種與供奉神靈來累積聲望，機制穩健且富有異國文化氣息。'),
	 ('叔叔的遺囑 (Last Will)','45-75 min','12+','2-5 人',NULL,'這是一個「看誰先把錢花光」的遊戲。玩家要在期限內透過奢華餐宴、買豪宅、帶寵物旅行來敗光家產以繼承遺產。'),
	 ('驢橋 (Eselsbrücke)','30-45 min','9+','3-6 人',NULL,'玩家要編造荒謬的故事來連結三個無關的圖案，並在幾回合後回憶出別人故事中的圖案。非常考驗大腦的記憶聯想力。'),
	 ('電力公司-澳洲地圖','90-120 min','12+','2-6 人',NULL,'澳洲地圖以偏遠地區的高昂連接費著稱，模擬了大洋洲的能源分佈特性。'),
	 ('歷史巨輪 (Through the Ages)','120-240 min','15+','2-4 人',NULL,'文明類桌遊的巔峰。從古代到現代，玩家需平衡科技、農業、軍事與文化。沒有版圖，純粹靠卡牌與數值堆疊出的史詩感。'),
	 ('妙探尋兇 (Cluedo)','45 min','9+','3-6 人',NULL,'在豪宅中尋找兇手、兇器與案發現場。經典的消去法推理遊戲，是偵探類型桌遊的開山鼻祖。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('叢林智慧棋 (Bumuntu)','30-45 min','9+','2-5 人',NULL,'根據動物的智慧進行移動。每種動物磁磚都有獨特的位移方式，玩家需收集磁磚並爭奪版圖權力。'),
	 ('國王堡傳奇 (Kingsburg)','90 min','9+','2-5 人',NULL,'玩家透過擲骰來「討好」國王的顧問，藉此換取資源建設領地，並在每年冬天抵禦外敵入侵。'),
	 ('諾丁漢警長 (Sheriff of Nottingham)','45-60 min','12+','3-5 人',NULL,'玩家要夾帶違禁品進城。警長會隨機抽查，你可以賄賂他或用真話欺騙他。是非常受歡迎的「嘴砲」策略遊戲。'),
	 ('CV人生履歷','45-60 min','9+','2-4 人',NULL,'透過骰子決定你的人生成就。你可以買房、結婚、升職或獲得特殊興趣，最後結算誰的人生最圓滿。'),
	 ('CV撰寫文明史','45-60 min','9+','2-5 人',NULL,'CV 系列續作。將規模放大到整個人類文明，透過收集文化與技術卡牌來打造輝煌歷史。'),
	 ('爆珠發明 (Gizmos)','40-50 min','15+','2-4 人',NULL,'利用彩色能量球啟動發明。精華在於卡牌間的「連鎖反應」，一次行動能帶動四五個獎勵，爽快感十足。'),
	 ('古巴：聖地牙哥 (Santiago de Cuba)','40-60 min','9+','2-4 人',NULL,'在古巴城市中經營生意。節奏輕快，玩家在車子抵達碼頭前必須準備好貨物，是極佳的輕策略遊戲。'),
	 ('活在當下 (Carpe Diem)','45-75 min','9+','2-4 人',NULL,'Stefan Feld 作品。玩家在古羅馬社區建設自己的區域，需滿足特定的排列條件來獲取最高分數。'),
	 ('俄羅斯鐵路 (Russian Railroads)','90-120 min','12+','2-4 人',NULL,'極致的分數爆炸感。玩家建設西伯利亞大鐵路，透過各種組合技讓分數呈倍數成長，重策愛好者必玩。'),
	 ('農家樂 (Agricola)','90-120 min','12+','1-4 人',NULL,'桌遊界的「痛苦流」神作。玩家要種田、養羊、蓋房子還要生小孩，但最可怕的是每到收穫季就要面臨「餵不飽家人」的壓力。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('農家樂-閤家歡樂版 (Agricola: Family Edition)','45 min','9+','1-4 人',NULL,'去除了複雜的職業與次要建設卡。保留核心玩法但大幅降低門檻，適合想接觸經典遊戲的家庭與新手。'),
	 ('太陽神的祭司 (Priests of Ra)','45-60 min','9+','2-5 人',NULL,'經典拍賣遊戲《太陽神 Ra》的變體。玩家透過有限的資源競標文物與板塊，是考驗風險評估的博弈之作。'),
	 ('石器時代 (Stone Age)','60-90 min','9+','2-4 人',NULL,'工放類型的入門聖經。玩家帶領部落成員採集資源、生小孩與建設，透過掷骰與機率管理來優化發展速度。'),
	 ('石器時代-兒童版 (My First Stone Age)','15-20 min','6+','2-4 人',NULL,'將石器時代簡化為記憶與收集機制。小朋友透過記憶板塊位置來換取資源蓋房子，曾獲年度最佳幼兒遊戲獎。'),
	 ('五大部落 (Five Tribes)','40-80 min','12+','2-4 人',NULL,'在一千零一夜背景下，利用獨特的「播種」機制移動米寶，觸發不同的部落能力。每一步都充滿了計算與搶先機的快感。'),
	 ('蓋亞計劃 (Gaia Project)','120-150 min','15+','1-4 人',NULL,'《神秘大地》的太空版。玩家控制擁有獨特能力的種族在星際間擴張。機制極度嚴謹且平衡，是目前全球策略遊戲的頂點之一。'),
	 ('奈斯爾傳奇 (Sabika)','60-120 min','15+','1-4 人',NULL,'玩家扮演納斯里德王朝的貴族，參與阿爾罕布拉宮的建設。獨特的三重輪盤機制，讓玩家在建設、貿易與詩歌創作間進行深度抉擇。'),
	 ('巨魔與公主 (Trolls and Princesses)','90-120 min','12+','2-4 人',NULL,'玩家率領巨魔部落，透過挖礦、變身以及「綁架」公主來獲得聲望。畫風精美且機制充滿童話色彩。'),
	 ('曼陀羅石 (Mandala Stones)','30 min','9+','2-4 人',NULL,'極具美感的抽象遊戲。玩家在版圖上收集彩色石頭，並在個人圖板上疊放計分，考驗空間規劃與時機掌控。'),
	 ('佛羅倫斯王子 (Princes of Florence)','75-100 min','12+','1-5 人',NULL,'經典德式策略。玩家在文藝復興時期吸引藝術家與學者，透過競標建築與景觀來打造最負盛名的家族領地。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('黑幫動物園 (Mafiozoo)','60 min','12+','2-4 人',NULL,'玩家在動物城市中爭奪黑幫老大的位置。透過賄賂政府官員或佔領領地來累積影響力，畫風幽默但競爭激烈。'),
	 ('瀑布淘金客 (Niagara)','30-45 min','9+','3-5 人',NULL,'曾獲德國年度遊戲大獎。實體流動的河流版圖，玩家要划船搶金礦，需小心不要被瀑布沖下去！'),
	 ('古董局中局','45-60 min','12+','6-8 人',NULL,'改編自知名小說。玩家分為許願、老朝奉兩大陣營，在鑑定古董真偽的過程中隱藏身分並尋找隊友。'),
	 ('東海道 (Tokaido)','45 min','9+','2-5 人',NULL,'一場優雅的京都旅行。玩家在旅程中吃美食、看風景、買特產。規則簡單卻充滿禪意，是視覺與心靈的雙重享受。'),
	 ('浪漫花匠坊','30-45 min','9+','2-4 人',NULL,'玩家規劃自己的花房。透過精美的花朵板塊配置來達成顧客需求，是一款主題柔和、難度適中的作品。'),
	 ('萌鼠摘月','30 min','9+','1-5 人',NULL,'可愛的平衡疊疊樂。玩家要幫助老鼠們搭梯子爬上月球，考驗手部穩定度與積木放置的巧思。'),
	 ('太空基地 (SPACE BASE)','45-60 min','9+','2-5 人',NULL,'升級版的骰子街。即使在別人的回合，你的太空站也能根據點數產出資源。連鎖反應帶來的爽快感非常高。'),
	 ('勃根地城堡 (The Castles of Burgundy)','30-90 min','12+','2-4 人',NULL,'傳奇設計師 Stefan Feld 的代表作。利用兩顆骰子執行拿取板塊、放置或貿易行動，是德式桌遊中機制最優雅的經典之一。'),
	 ('洞穴農夫 (Caverna: The Cave Farmers)','30-210 min','12+','1-7 人',NULL,'《農家樂》的精神續作。玩家扮演矮人家庭，在開墾森林的同時還要挖掘洞穴。自由度更高，且增加了探險機制。'),
	 ('蓋亞計劃-失落的艦隊擴充','120-180 min','15+','1-4 人',NULL,'為蓋亞計劃增加了新的種族、新的科技軌以及可以探索的「失落艦隊」，大幅提升了原本就極高的耐玩度。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('聖彼得大教堂','60-90 min','12+','2-4 人',NULL,'玩家參與梵蒂岡大教堂的修建。需管理勞動力與建築材料，透過貢獻來獲得教會的聲望。'),
	 ('瘟疫危機 (Pandemic)','45 min','9+','2-4 人',NULL,'全球最知名的合作桌遊。玩家各自具備專業職能，需在全球疫情爆發前研發出四種疫苗，拯救全人類。'),
	 ('期貨時代 (Hab & Gut)','45 min','9+','3-5 人',NULL,'玩家與鄰座共用市場資訊。你必須判斷股價漲跌並在最佳時機買賣，但遊戲結束時捐獻公益最少的人會直接判定落敗。'),
	 ('輝煌的羅倫佐 (LORENZO IL MAGNIFICO)','60-120 min','12+','2-4 人',NULL,'玩家身為佛羅倫斯貴族。本局骰子的點數決定了所有玩家工人的強度，策略感極強，需在宗教、資源與建設間取捨。'),
	 ('東京之王 (King of Tokyo)','30 min','9+','3-6 人',NULL,'玩家扮演怪獸入侵東京。透過擲骰攻擊對手或回血，最後存活下來或先得滿 20 分者為王。節奏極快。 '),
	 ('維京山谷滾球大賽 (Valley of the Vikings)','15-20 min','6+','2-4 人',NULL,'結合了打保齡球的物理機制與戰術卡位的遊戲。需精準滾動大球擊倒木樁，讓維京人在碼頭移動來獲取金幣。'),
	 ('聖彼得堡 (Saint Petersburg)','45-60 min','9+','2-5 人',NULL,'經典的資源轉化與建設遊戲。平衡工人的收入與貴族的分數，在多個回合中建立最強的得分體系。'),
	 ('圖拉真 (Trajan)','60-120 min','12+','2-4 人',NULL,'大師 Stefan Feld 作品。核心機制為古老的「播種」移動。六個行動區塊環環相扣，極其燒腦且具備多樣的得分路線。'),
	 ('橫濱紳商會 (Yokohama)','90 min','12+','2-4 人',NULL,'玩家在明治時期的橫濱推行貿易。獨特的「工人路徑」放置方式，讓每一步移動都需要精算成本與阻隔對手。'),
	 ('遊惡園 (The Bad Karmas)','30-45 min','9+','2-5 人',NULL,'充滿惡搞氣息的遊樂園經營。玩家要打造能吸引遊客（但可能讓他們吐出來）的驚險設施，比的是誰能賺到最多黑心錢。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('遊惡園-擴充','30-45 min','9+','1-5 人',NULL,'增加了更多的遊樂設施卡與事件，讓遊惡園的經營過程變得更加混亂與爆笑。'),
	 ('柯爾特快車 (Colt Express)','40 min','9+','2-6 人',NULL,'在 3D 火車模型上進行的大劫案。玩家需預先規劃行動卡，但執行時常因為別人的干擾而發生打錯人或對空氣開槍的趣事。'),
	 ('柯爾特快車-車馬飛渡擴充','40-50 min','9+','2-6 人',NULL,'加入了馬車模型。玩家可以在行駛的火車與馬車間跳躍，增加了戰術空間與更豐富的搶劫目標。'),
	 ('妙語說書人 迪士尼版 (Dixit: Disney Edition)','30 min','9+','3-6 人','bg_1774760455797.jpeg','經典說書人規則結合迪士尼動畫名場面。畫面夢幻感十足，是迪士尼粉絲與家庭聚會的首選。'),
	 ('神秘大地 (Terra Mystica)','60-150 min','15+','2-5 人',NULL,'世界頂尖策略遊戲。14 個截然不同的種族在版圖上改造地形並擴張城市。完全無隨機性，純粹考驗長遠規劃。'),
	 ('神秘大地-擴充','60-150 min','15+','2-5 人',NULL,'增加了新的城鎮板塊、加分板與平衡修正，讓基礎遊戲的變化度更上一層樓。'),
	 ('神秘大地-冰與火擴充','60-150 min','15+','2-5 人',NULL,'增加了 6 個超強大的新種族（如冰雪巨人、火龍等），以及新的地圖與計分方式，是神秘大地的必收擴充。'),
	 ('帝都爭霸 (After The Empire)','60-120 min','15+','2-4 人',NULL,'玩家建設自己的城堡並抵禦外敵入侵。實體城牆配件非常吸睛，需在發展經濟與軍事防禦間取得極度平衡。'),
	 ('幕後交易 (The Dealmaker)','30-45 min','9+','3-5 人',NULL,'充滿談判的派對策略。玩家手中握有資源，必須透過不斷與他人溝通、交換來達成特定契約以獲分。'),
	 ('滲透因子 (Infiltration)','45 min','9+','2-5 人',NULL,'玩家扮演駭客潛入高科技設施。你需決定要貪心深入拿更多資料，還是在警衛抵達前先帶著現有的成果逃脫。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('迷因在說話 (Meme Talk)','20-30 min','12+','2-6 人','bg_1774760531422.jpeg','利用各種流行的迷因梗圖來回答題目，考驗大家的幽默感與對網路文化的熟悉度。'),
	 ('狼人真言 (Werewords)','10 min','9+','4-8 人',NULL,'將狼人殺與猜詞結合。全隊要在時間內猜中謎底，狼人會暗中誤導，先知會暗中引導，過程極其緊湊。'),
	 ('奇片總裁的爆衣戀曲','20-40 min','12+','2-6 人',NULL,'由台灣知名漫畫家「奇片」授權。充滿荒誕劇情與爆笑爆衣元素，適合親朋好友一起體驗奇片式的惡趣味。'),
	 ('生態公園 (Ecosystem)','20-30 min','9+','3-5 人',NULL,'玩家建立自己的生態系，不同物種在特定位置或組合下能產出高分（如狼在森林、鹿在水源旁）。'),
	 ('禮尚往來 (That''s Not a Hat)','15 min','9+','3-8 人',NULL,'規則極其簡單卻異常困難的記憶遊戲。玩家不斷交換手中蓋著的禮物，若你忘記它是什麼卻被抓到吹牛就輸了。'),
	 ('成雙成對 (Pairs)','15 min','9+','2-8 人',NULL,'規則只有一句話：不要拿到成對的牌。簡單刺激的墊檔遊戲，適合在等待聚會開始前玩幾把。'),
	 ('情書 (Love Letter)','10-20 min','9+','2-4 人',NULL,'僅用 16 張牌建構出的心理戰神作。玩家要設法淘汰對手，將情書送到公主手中。簡單卻耐玩。'),
	 ('呆瓜! 呆瓜! 大呆瓜! (Fou! Fou! Fou!)','15-20 min','9+','3-8 人',NULL,'玩家需同時遵循多個荒謬的規則（如：出紅色要起立、出偶數要拍桌）。規則會隨時間累積，出錯的人就是大呆瓜！'),
	 ('集合吧！白白鐵人！','20 min','9+','4-4 人',NULL,'以知名角色「白白」為主題。需四人共同合作、或特定條件下進行互動，是一款充滿療癒與歡笑的遊戲。'),
	 ('宿命的旅團 (FELLOWSHIP OF FATE)','30-45 min','12+','1-5 人',NULL,'玩家輪抽不同的職業冒險者並派遣他們。每位冒險者有兩種能力，需根據當前資源與對手動向靈活切換。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('浮言浪語','30 min','12+','2-6 人',NULL,'透過各種誇張或反諷的對話來推進遊戲。非常適合愛演、愛開玩笑的群體共同體驗。'),
	 ('瘋狂地下城','45 min','9+','2-4 人',NULL,'玩家探索變幻莫測的地下城。需在混亂的走廊中避開怪物並搶走最多的寶藏。'),
	 ('遇見小說','30-45 min','12+','3-6 人',NULL,'利用小說中的經典名句來對話或解決難題。充滿文學氣息與出人意料的對話聯結。'),
	 ('瘋魔口袋 (Pocket Madness)','30 min','9+','2-4 人',NULL,'輕快的小品遊戲。玩家收集克蘇魯神話中的地點與怪物卡。需控制發瘋點數，最先讓對手崩潰的人獲勝。'),
	 ('PaiMiAhhh (怪七八糟)','15-20 min','9+','4-4 人',NULL,'充滿台灣味的在地主題遊戲。節奏快速、規則無厘頭，是炒熱聚會氣氛的最佳利器。'),
	 ('大排檔 (CHOPE!)','20 min','9+','2-6 人',NULL,'模擬新加坡大排檔搶位子的習俗。玩家要快速用面紙盒「佔位」並搶奪食物卡，過程熱鬧混亂。'),
	 ('骰子算算 (minus plusus)','15-20 min','6+','2-10 人',NULL,'訓練加減運算的反應遊戲。適合小朋友練習基礎數學，也能作為大人聚會中的簡單熱身。'),
	 ('宇航音訊拼圖：火星求生 (Tele Craft)','20-30 min','9+','2-4 人',NULL,'玩家扮演火星基地的通訊員，透過零碎的語音訊息拼湊出正確的地圖導航。考驗資訊傳遞的精準度與空間邏輯。'),
	 ('搜捕農場動物','15 min','6+','2-4 人',NULL,'農場動物逃跑了！玩家要在混亂的版圖中快速找出指定的動物。適合幼兒與家長同樂的反應類小品。'),
	 ('SUSHI！GO！ (迴轉壽司)','15-20 min','9+','3-5 人',NULL,'經典的壽司輪抽遊戲。玩家選一張牌後將整疊手牌傳給下家，設法湊出最高分的壽司組合（如三張生魚片、最多的握壽司）。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('松鼠也瘋狂 (Nuts!)','20 min','6+','2-4 人',NULL,'松鼠們在森林裡埋藏了橡實。玩家需記憶位置並在對手搶走前挖掘出來，是一款畫風可愛的記憶型博弈遊戲。'),
	 ('客人來之前 (Before the Guests Arrive)','20-30 min','9+','2-4 人',NULL,'日系清新風格。玩家要在客人上門前的有限時間內，整理房間、準備茶點並打掃乾淨，考驗資源管理的優先順序。'),
	 ('電梯前 (In Front of the Elevators)','20 min','9+','2-4 人',NULL,'在電梯前插隊吧！玩家打出家庭成員卡，利用特定身份（如老奶奶、小孩）的優先權來插隊，設法讓自己的家族成員擠進電梯。'),
	 ('腹黑菓子店','30 min','9+','3-6 人',NULL,'外表精美的點心，背後可能是陷阱！玩家互相贈送菓子，需透過觀察對手的神情與言詞，判斷這份禮物是分數還是負擔。'),
	 ('Pitaka君 (ピタカックン)','15 min','6+','2-6 人',NULL,'可愛的磁鐵互動遊戲。玩家要根據卡片指示，快速完成指定的磁力組合或圖案，是一款非常動感的小品。'),
	 ('猜拳歷險','15 min','6+','2-6 人',NULL,'將經典的「剪刀、石頭、布」轉化為冒險路徑。玩家透過猜拳決定前進步數，簡單卻充滿變數與笑聲。'),
	 ('福爾摩斯13 (13 Clues)','15-30 min','9+','2-4 人',NULL,'邏輯推論的神作。玩家要找出自己面前的三張謎底卡（人物、地點、證物），透過向對手提問並在筆記本上記錄排除法。'),
	 ('眾神大典','30-45 min','12+','2-6 人',NULL,'玩家扮演眾神，在慶典中競爭影響力。每位神明擁有獨特神力，需精準運用技能來掌控版圖上的局勢。'),
	 ('亞瑟傳奇 (Legend of Arthur)','30-60 min','12+','4-10 人',NULL,'《阿瓦隆》的正統進化版。加入了更多變的角色與任務機制，梅林與刺客的對決在亞瑟王的圓桌上更加劇烈。'),
	 ('萌犬紳士 (Dog Lover)','30 min','9+','2-4 人',NULL,'玩家要收養不同的狗狗，餵養牠們、教導特技並散步。需在有限行動中滿足狗狗的需求以獲取高分。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('萌貓淑女 (Cat Lady)','15-30 min','9+','2-4 人',NULL,'超受歡迎的輕策略遊戲。玩家收集貓咪、飼料、玩具與貓草。若貓咪沒被餵飽會倒扣分，美術風格深受女性玩家喜愛。'),
	 ('盜夢都市 (Inception Tabletop)','45-60 min','12+','3-10 人',NULL,'啟發自電影《全面啟動》。玩家分為夢境守衛與盜夢者。在層層夢境中，你必須識破誰在植入意識、誰在守衛秘密。'),
	 ('你在''喵''我嗎？','15 min','9+','2-10 人',NULL,'玩家要根據卡片指示發出特定的貓叫聲或做出動作，讓其他玩家猜出你的指令。是一款門檻極低、笑果極佳的遊戲。'),
	 ('數字火車 (The Game: Quick & Easy)','10-20 min','9+','1-100 人',NULL,'全體玩家合作將卡牌按序放入軌道。規則極簡，但不能透露手牌具體數值，挑戰全體默契的極限。'),
	 ('Seven！','15-20 min','6+','3-5 人',NULL,'玩家需記憶對手曾打出或詢問過的卡牌，設法奪取對方手中的數字卡，目標是率先湊齊七組不同顏色的牌。'),
	 ('甜點大胃王','20-30 min','9+','2-10 人',NULL,'模擬大胃王比賽。玩家要拼命吃下各種甜點卡，但要小心吃到「胃痛卡」或被對手干擾，是一款氣氛熱鬧的聚會小品。'),
	 ('龍牙勇者','30 min','9+','3-5 人',NULL,'勇者們要組隊打龍，但誰都不想出力。玩家秘密出牌決定戰鬥力，如何在不被抓到的情況下混分是生存之道。'),
	 ('皂單全收 (Soap Opera)','20 min','9+','3-6 人',NULL,'別讓肥皂掉地上了！玩家需快速反應並接下或傳遞「肥皂」，是一款考驗反應神經與手速的惡搞遊戲。'),
	 ('九九將','20-30 min','9+','2-4 人',NULL,'將傳統麻將機制大幅簡化。玩家在九宮格中進行摸打與組合，保留了麻將的聽牌感但節奏快上許多。'),
	 ('奇獸競技場','30 min','9+','2-4 人',NULL,'玩家召喚並控制奇獸在競技場對決。透過擲骰驅動技能，合理分配骰子點數來攻擊、防禦或蓄力。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('年獸 (Nian)','20 min','9+','3-3 人',NULL,'專為三人設計。玩家透過出牌控制年獸的移動，設法保護自己的家園並讓對手遭遇年獸侵襲。'),
	 ('文明時代 (Age of Civilization)','30-45 min','9+','1-4 人',NULL,'將龐大的文明遊戲濃縮在小盒子裡。每一輪你都會興起一個新文明並讓舊文明成為遺產，策略密度極高。'),
	 ('天堂！我要進來了！','20 min','12+','5-10 人',NULL,'瘋狂的入關審核。玩家需想方設法符合進入天堂的荒謬條件。是一款人越多越好玩的混亂系派對遊戲。'),
	 ('綜合口味的戀愛習題','30-45 min','12+','3-10 人',NULL,'與知名插畫家「綜合口味」聯名。玩家透過討論戀愛中的情境來增進彼此了解，非常適合聯誼或老友聚會。'),
	 ('亡命歡樂','20-30 min','12+','3-10 人',NULL,'刺激的逃脫主題。玩家要在緊迫的時間壓力下執行特定動作或指令，氣氛非常焦慮且爆笑。'),
	 ('歡迎來到地下城 (Welcome to the Dungeon)','20-30 min','9+','2-4 人',NULL,'每個人都在扣除英雄的裝備或增加地城的怪物。你需判斷剩下的裝備是否能活著走完地城，或在陷阱挖好時果斷 Pass 讓對手去送死。'),
	 ('就算是無雙勇者也怕遇上這款豬隊友','30 min','9+','3-6 人',NULL,'玩家合作對抗魔王，但每個人都被分配了搞笑的缺點。你必須克服這些豬隊友行為來達成勝利。'),
	 ('三千世界鴉殺盡','20 min','12+','2-4 人',NULL,'以日本古風為背景。玩家透過出牌擊落烏鴉或保護自己的美夢。風格唯美，規則簡練而有層次。'),
	 ('水瓶座 (Aquarius)','20 min','6+','2-5 人',NULL,'類似接龍。玩家輪流放置元素卡，設法將自己祕密身分代表的元素連在一起。美術風格復古清新。'),
	 ('獴鷲歡樂','15 min','9+','2-5 人',NULL,'簡單明快的卡牌對決。玩家同時出牌競爭高分或避開負分，規則簡練適合各年齡層。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('英雄總是最後一個到','20-30 min','9+','3-5 人',NULL,'這是一個比慢的遊戲。玩家要在戰場上摸魚，設法在最後關頭才抵達，充滿了惡搞傳統英雄主義的趣味。'),
	 ('皇家港 (Port Royal)','20-50 min','9+','2-5 人',NULL,'經典的「見好就收」遊戲。玩家翻開碼頭卡，可以一直翻到出現兩艘同色船為止。累積金幣招募夥伴並解開任務。'),
	 ('動物通緝令','15 min','6+','2-5 人',NULL,'玩家要從快速翻開的牌中找出符合通緝條件的動物特徵。訓練專注力與大腦反射速度。'),
	 ('政變疑雲 (Coup)','15 min','9+','2-6 人',NULL,'每人只有兩張牌身分。你可以宣稱自己擁有任何能力（如刺殺或偷錢），但若被拆穿謊言就會失去身分，最後倖存者獲勝。'),
	 ('一夜終極政變 (One Night Ultimate Coup)','10 min','9+','3-10 人',NULL,'將政變與一夜狼機制結合。縮短了博弈時間，大幅提升了推理與混亂程度，是極佳的開場遊戲。'),
	 ('恐怖村','30-45 min','12+','2-5 人',NULL,'在充滿詭異氣息的村莊中，玩家需找出潛伏其中的邪惡存在。強調壓抑的氣氛營造與身分隱藏。'),
	 ('未命名農場生物 (Untitled Goose Game / Farm variant)','20 min','9+','2-7 人',NULL,'靈感來自《鵝作劇》。玩家扮演搗蛋的農場生物，設法破壞人類的計畫，是一款人越多越吵、越好玩的遊戲。'),
	 ('今夜不回家','20 min','12+','2-6 人',NULL,'模擬狂歡夜晚。玩家要處理各種突發狀況以延長玩樂時間，充滿了各種生活化的笑梗與互動。'),
	 ('無雙魔藥 (Only One Collection)','20 min','9+','2-4 人',NULL,'這是一個「只能收集一個」的殘酷遊戲。如果你收集了兩瓶同樣的魔藥，分數就會歸零。考驗精算與阻礙對手的能力。'),
	 ('結印魔法師','20 min','9+','3-6 人',NULL,'玩家需快速做出正確的結印手勢來發動魔法。考驗手眼協調與對符號的辨識能力。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('迷宮機器人 (MICRO ROBOTS)','20 min','9+','2-100 人',NULL,'在迷宮版圖上規劃最短路徑。所有玩家同時心算機器人需經過幾次移動到達目標。理論上可支援極多人共同競速。'),
	 ('從前從前 (Once Upon a Time)','30-45 min','9+','2-6 人',NULL,'合作敘事遊戲。玩家利用手中的元素卡共編一個童話故事，設法把故事引導向自己手中的結局卡。非常有創意。'),
	 ('英雄麥來亂','30 min','9+','2-5 人',NULL,'當英雄成為困擾時該怎麼辦？玩家要處理這些闖禍的英雄，利用機制將麻煩丟給對手。'),
	 ('砰！ (BANG!)','20-40 min','9+','3-7 人',NULL,'西部牛仔主題。警長、副警長、歹徒與背叛者的生存鬥爭。需根據他人出牌與射擊對象來推敲身分。'),
	 ('砰！骰子版 (BANG! The Dice Game)','15 min','9+','3-8 人',NULL,'BANG! 的精簡進化。用擲骰取代手牌，節奏更快，且加入了印第安箭頭等機制，讓身分博弈更加緊湊刺激。'),
	 ('SET (神奇形色牌)','20 min','9+','1-100 人',NULL,'尋找三張牌組成一個「SET」。需判斷顏色、形狀、數量與填色是否全部相同或全部不同，是訓練右腦的高級教材。'),
	 ('糊塗動畫家','30 min','9+','2-4 人',NULL,'玩家要在有限時間內畫出關鍵幀，設法讓隊友聯想出原本的動畫主題。是一款充滿笑聲的創作遊戲。'),
	 ('文獻室 (Biblios)','30 min','9+','2-4 人',NULL,'玩家扮演中世紀修道院長。遊戲分為分配資源與競標兩個階段，需精準判斷卡片價值，並透過骰子操控各類文獻在結束時的得分倍率。'),
	 ('密室逃脫-遺棄的小屋 (EXIT: The Abandoned Cabin)','60-90 min','12+','1-4 人',NULL,'EXIT系列最經典的入門款。玩家被困在荒野小屋，需利用轉盤、書本與各種配件解開謎題。注意：遊戲過程中可能會破壞配件。'),
	 ('動物夜怕怕','20 min','9+','4-12 人',NULL,'夜晚的農場充滿驚喜！玩家需根據翻開的卡片快速做出對應動物的動作或聲音，是一款人越多越混亂、越好玩的反應遊戲。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('回憶三重奏 (TRIO)','15 min','6+','3-6 人',NULL,'2024年熱門小品。玩家需找出手牌或桌面上三張數字相同的卡片。規則極簡，但需觀察他人的詢問紀錄來推敲數字位置。'),
	 ('人類毀滅計劃','30-45 min','15+','4-16 人',NULL,'充滿黑色幽默的陣營遊戲。玩家分為不同派系，在充滿荒誕感的末日背景下，透過投票與功能卡決定人類的命運。'),
	 ('血與刃的白薔薇','30-50 min','12+','5-10 人',NULL,'日系風格的陣營遊戲。玩家身處暗殺與保衛的風暴中，需透過出牌戰鬥來確認彼此身分並保護自己的首領。'),
	 ('就這樣我成了聖劍王','30 min','9+','4-5 人',NULL,'幽默的奇幻主題。玩家競爭拔出聖劍的機會，需在冒險過程中累積實力，同時預防被其他競爭者「暗算」。'),
	 ('惡鄰亂鬥','20-30 min','9+','2-6 人',NULL,'你的鄰居很吵嗎？這款遊戲讓你合法搗蛋！玩家利用各種誇張的干擾卡（如：深夜派對、漏水）讓鄰居崩潰獲勝。'),
	 ('曠世發明 (Innovation)','45-60 min','12+','2-4 人',NULL,'極具深度的卡牌遊戲。從石器到資訊時代，每張卡牌都有改變規則的強力效果。玩家需建立科技引擎並適時發動攻擊。'),
	 ('極限攻頂 (Can''t Stop)','30 min','9+','2-6 人',NULL,'經典的「停不下來」。玩家擲四顆骰子並組合成兩個數字來前進，你可以一直擲下去，但只要沒達成數字就會失去進度。充滿賭徒心理。'),
	 ('靈獸伏魔錄','40 min','9+','3-5 人',NULL,'玩家控制不同的靈獸進行封印與戰鬥。需配合屬性相剋與特殊符咒來擊敗妖魔，美術風格獨具東方韻味。'),
	 ('炸彈競技場 (Boomblast!)','20-30 min','9+','4-9 人',NULL,'節奏極快的生存遊戲。玩家秘密分隊，在炸彈飛來飛去的競技場中，設法活到最後或讓對手全隊淘汰。'),
	 ('炸彈競技場-基地爭霸戰','30 min','9+','2-8 人',NULL,'引入了基地防禦概念。玩家不只要炸毀對手，還得加強自己防區的工事，增加了策略維度與博弈空間。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('煉金數士 (Counting Alchemist)','20 min','6+','2-6 人',NULL,'將基礎數學運算融入煉金配方。玩家需快速計算出正確的元素數值來完成藥水，是寓教於樂的佳作。'),
	 ('友善的魔物與酒館英雄','30-45 min','9+','2-4 人',NULL,'反轉傳統設定。魔物也可以很友善！玩家扮演酒館老闆，試著媒合冒險英雄與魔物和諧共處，獲取名聲。'),
	 ('割喉冒險隊 (Cutthroat Caverns)','60 min','12+','3-6 人',NULL,'大家必須合作打怪，但只有「尾刀」殺死怪物的人才有分！這導致玩家會互相扯後腿，直到魔王出現才驚覺戰力不足。'),
	 ('獵巫鎮 (Salem 1692)','25-35 min','12+','4-12 人',NULL,'在塞勒姆審巫案背景下，女巫可以透過傳遞卡片「感染」村民，讓村民也變成女巫。身分會流動，緊張感滿分。'),
	 ('海賊對決','20 min','9+','3-8 人',NULL,'簡單刺激的卡牌博弈。海賊們為了分贓而大打出手，利用卡牌組合來搶奪金幣，節奏明快。'),
	 ('未確認生物 (CRYPTID)','30-50 min','9+','3-5 人',NULL,'每人掌握一條關於生物棲息地的獨家線索（如：在森林或山脈）。透過在地圖上詢問對手，整合所有線索找出唯一的格子。'),
	 ('老二哲學','20 min','9+','2-6 人',NULL,'這不是比第一名的遊戲，而是比誰能巧妙地當「老二」。拿捏分數的中間值是生存的關鍵，充滿戲弄對手的樂趣。'),
	 ('犯人在哪裡','20-30 min','9+','3-8 人',NULL,'在一堆嫌疑犯中，根據零碎的證詞找出真正的犯人。考驗玩家對圖像細節的記憶力與聯想力。'),
	 ('暑假日記','30 min','9+','3-6 人',NULL,'溫馨的小品遊戲。玩家要規劃暑假的活動，收集昆蟲、寫日記、去海邊。比誰的暑假過得最充實精彩。'),
	 ('教父風雲：危情古巴 (Mafia de Cuba)','20-30 min','12+','6-12 人',NULL,'玩家輪流從雪茄盒拿取鑽石或身分代幣。教父必須審問每個人，根據剩餘鑽石數量與表情抓出小偷。配件質感極佳。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('教父風雲-擴充','20-30 min','12+','6-12 人',NULL,'加入了更多有趣的身分，如革命家或貪汙警察，讓原本就混亂的審問現場變得更加難以捉摸。'),
	 ('彩虹小鎮','30 min','9+','2-5 人',NULL,'輕鬆的建設遊戲。玩家在彩虹下建設彩色房屋，設法讓同色建築相連來獲取高分，色彩鮮豔奪目。'),
	 ('偉人的猜拳戰略','20 min','9+','3-6 人',NULL,'歷史上的偉人靈魂附體！透過猜拳決定戰術，每位偉人有不同的猜拳加成或反擊能力，惡搞味十足。'),
	 ('功夫 (Kung Fu)','30 min','9+','2-5 人',NULL,'玩家組合招式卡來進行決鬥。需預判對手的防禦位並打出致命的一擊，是一款充滿節奏感的卡牌對戰遊戲。'),
	 ('多米諾王國 (Kingdomino)','15-20 min','9+','2-4 人',NULL,'曾獲年度遊戲大獎。玩家挑選地圖板塊拼放在 5x5 的領地內，需考慮皇冠數量與同型地形面積，規則簡單但策略極其紮實。'),
	 ('大富翁-希臘之旅','60-90 min','6+','2-10 人',NULL,'以希臘名勝為主題的大富翁。將房地產換成愛琴海小鎮，帶領玩家在遊戲中環遊浪漫的希臘群島。'),
	 ('大富翁-四季節慶之旅','45-60 min','6+','2-4 人',NULL,'環繞四季不同節日的地圖。結合節慶習俗的隨機事件卡，適合節日時全家人一同遊玩。'),
	 ('大富翁-超級百貨','45 min','6+','1-4 人',NULL,'玩家在百貨公司內經營專櫃，目標是成為百貨大亨。地圖設計成樓層結構，購物與經營感十足。'),
	 ('大富翁-職業之旅','45-60 min','6+','2-4 人',NULL,'讓小朋友認識不同職業。玩家在移動過程中體驗升遷、轉職與薪資管理，具備初步的社會化教育意義。'),
	 ('大富翁-三用棋','20-60 min','6+','2-2 人',NULL,'收錄了西洋棋、跳棋與象棋三種經典棋類。適合訓練邏輯思考與策略布局，一套多玩的長青首選。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('心靈共感 (The Mind)','20 min','9+','2-12 人',NULL,'全體玩家不能說話，需憑直覺將手牌依數字從小到大打出。挑戰全隊是否能在同個波長上，成功時成就感極高。'),
	 ('數字配方 (Number Recipe)','15 min','6+','2-6 人',NULL,'玩家根據食譜要求的數字總和，投入食材卡進行湊數。訓練基礎心算速度與手牌規劃。'),
	 ('貓咪比薩捲餅羊 (Taco Cat Goat Cheese Pizza)','10 min','6+','2-8 人',NULL,'口中念著「貓、比、薩、捲、餅、羊」，當口中說的跟牌面一樣時快速拍擊桌面。簡單洗腦且會讓人拍到手軟的派對神作。'),
	 ('跳舞機器人 (Dancing Robot)','15-20 min','6+','2-6 人',NULL,'玩家要記住並重複機器人的舞蹈動作序列。隨機關卡增加，動作越來越多，適合小朋友律動與大腦訓練。'),
	 ('呱呱跳 (Hop It!)','15 min','6+','2-4 人',NULL,'控制青蛙模型進行彈跳比賽。設法精準彈入池塘中央的荷葉上，是訓練手部小肌肉協調的體感遊戲。'),
	 ('貓捉老鼠','15-20 min','6+','2-4 人',NULL,'經典的追逐機制。老鼠想偷起司，貓想抓老鼠。透過簡單的骰子或卡牌驅動移動，充滿緊張感的親子遊戲。'),
	 ('動物農場 (Animal Farm)','20-30 min','9+','2-4 人',NULL,'玩家經營自己的小農場。需妥善規劃畜牧區與農作物，並在市場波動中換取最高價值的收穫。'),
	 ('搞笑瑜珈 (Yogi)','20 min','9+','3-10 人',NULL,'抽卡並執行指示（如：左手摸右耳、下巴夾住卡牌）。你的姿勢必須一直保持，直到累積到你失去平衡為止，場面極其混亂。'),
	 ('肥貓小幫手','15 min','6+','2-2 人',NULL,'專為兩人設計的小品。協助肥貓完成家事或收集物品，節奏輕鬆，適合親子或情侶暖場使用。'),
	 ('盜鼠覬食','20 min','9+','2-5 人',NULL,'玩家扮演隱藏身分的老鼠，設法偷走最多的起司。需互相猜測誰才是真正的盜賊首領並進行阻攔。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('醜娃娃 (Uglydoll)','15 min','6+','2-6 人',NULL,'當桌面上出現三張一樣的醜娃娃時快速搶奪！節奏極快，畫風獨特，是小朋友非常著迷的反應卡牌遊戲。'),
	 ('麻吉貓放假去','20-30 min','6+','2-4 人',NULL,'台灣知名角色「麻吉貓」聯名。玩家帶著麻吉貓環島旅行，收集美食與紀念品，是一款溫馨療癒的台灣原創桌遊。'),
	 ('彩虹數列 (TEN)','20-30 min','9+','2-5 人',NULL,'翻開卡片嘗試湊出 1 到 10 的連號。你可以選擇繼續翻牌獲取更多，但只要總和超過 10 就會爆掉。結合了風險管理與標價機制。'),
	 ('世界上有兩種人','30 min','12+','2-9 人',NULL,'透過各種二選一的難題（如：洗澡先洗頭還是先洗身）來觀察朋友圈的喜好。是一款能快速了解彼此生活習慣的趣味派對遊戲。'),
	 ('無間風雲 (Good Cop Bad Cop)','20-30 min','12+','4-8 人',NULL,'警局裡有臥底！玩家擁有多張身分卡（好警察/壞警察/首領），需透過裝備卡偵查他人或直接射擊。是一款充滿槍戰感的陣營遊戲。'),
	 ('選書師 (The Biblios)','30-45 min','12+','3-8 人',NULL,'玩家扮演書店職員，需根據顧客稀奇古怪的需求（如：剛失戀、想變美），從書卡中挑選最合適的書籍並說服對方。'),
	 ('拼了！小雞','15-20 min','6+','2-4 人',NULL,'玩家要拼湊小雞版塊來完成指定的圖樣。規則簡單、色彩鮮艷，是訓練孩子空間組合能力的入門好選擇。'),
	 ('杏仁核 (Amygdala)','60-90 min','12+','2-4 人',NULL,'抽象且深度的策略遊戲。玩家在大腦中管理各種情感資源，並在杏仁核區域爭奪影響力，視覺美術風格非常獨特。'),
	 ('終極審判電車難題 (Trial by Trolley)','30 min','15+','3-10 人','bg_1774760431168.jpeg','著名的倫理難題變身桌遊。玩家分成兩組，說服列車長撞向另一條軌道。充滿垃圾話與價值觀衝擊，適合玩得起的朋友。'),
	 ('璀璨高塔 (Geo High Tower)','20 min','9+','2-4 人',NULL,'玩家利用幾何方塊向上堆疊高塔。不只要考慮高度，還要確保重心的穩定，是一款結合物理平衡與空間思維的遊戲。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('拼接建築師 (TANGRAMINO)','15-30 min','6+','1 人',NULL,'經典的索馬方塊/七巧板變體。提供多種關卡手冊，玩家需利用指定的立體積木拼出圖卡上的形狀，訓練平面轉立體的思考。'),
	 ('酒店大亨-都會版','45-60 min','9+','2-4 人',NULL,'在現代都市中興建飯店。玩家購買土地並加蓋樓層，當對手停留在你的飯店時需支付房費。目標是併購對手成為酒店巨頭。'),
	 ('蟑螂捕手 (La Cucaracha)','15-20 min','6+','2-4 人',NULL,'包含一隻會亂竄的電子蟑螂震動玩具！玩家需快速轉動餐具牆，將蟑螂引導進入自己的陷阱。刺激又吵鬧的派對遊戲。'),
	 ('害你在心口難開','20-30 min','9+','3-8 人',NULL,'每人頭上綁著一個禁忌詞或動作（只有別人看得到）。你要誘導對手說出或做出他頭上的內容，一旦犯規就出局。'),
	 ('得分沙拉 (Point Salad)','15-20 min','9+','2-6 人',NULL,'規則極簡但策略豐富。卡片正面是蔬菜，背面是計分方式。你要決定這張牌要拿來當「食材」還是當「目標」，變化萬千。'),
	 ('記憶黑洞','20 min','9+','2-6 人',NULL,'不僅要記住牌面，還要小心隨時出現的「黑洞」會讓你遺忘或弄混資訊。適合喜歡自我挑戰記憶極限的玩家。'),
	 ('禁忌之島 (Forbidden Island)','30 min','9+','2-4 人',NULL,'玩家合作在島嶼沉沒前收集四大神器。每一回合島嶼板塊都會陸續翻面（淹水），若不及時排水就會永久消失，壓力感十足。'),
	 ('詭鎮懸案-洛夫克拉夫特式推理','60-120 min','15+','1-8 人',NULL,'深度劇本推理遊戲。玩家調查阿卡漢小鎮的超自然案件，透過報紙、地圖與證詞拼湊真相。難度較高且充滿克蘇魯氛圍。'),
	 ('數大小 (Hurri Count)','15 min','6+','2-5 人',NULL,'比較大小與數量的快速反應遊戲。牌面上出現指定數量的動物時要搶拍，是訓練幼兒數感與專注力的極佳工具。'),
	 ('棒棒糖 (LOLLIPOPS)','15 min','6+','2-8 人',NULL,'玩家需快速找出與目標卡顏色配對正確的棒棒糖。色彩繽紛，適合低年級小朋友進行認知訓練。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('水果數到10','15 min','6+','2-5 人',NULL,'翻牌後，若盤中水果總數剛好等於 10 就拍鈴。是《心臟病》的數學進階版，能有效提升心算能力。'),
	 ('冰炫企鵝 (ICE COOL)','20 min','6+','2-4 人',NULL,'獲獎無數的彈指遊戲。玩家用手指彈射企鵝在立體校園盒中穿梭、吃魚並躲避訓導主任。企鵝的特殊造型能彈出弧線或跳躍。'),
	 ('小小貓頭鷹 (Hoot Owl Hoot!)','15 min','0+','2-4 人',NULL,'一款完全合作的幼兒遊戲。大家要幫助所有貓頭鷹在太陽升起前回到窩裡。沒有輸贏競爭，只有團隊合作。'),
	 ('龜兔蘿蔔賽跑','20 min','6+','2-6 人',NULL,'翻拍經典寓言，加入「蘿蔔」作為能量資源。玩家需平衡衝刺速度與體力，適合親子共玩的輕鬆賽跑遊戲。'),
	 ('動物疊疊樂 (Animal Upon Animal)','15 min','0+','2-4 人',NULL,'HABA 經典名作。玩家要把各種奇形怪狀的木製動物疊上去而不倒塌。訓練手部肌肉穩定度與平衡感。'),
	 ('泡泡大探險','10 min','0+','1-2 人',NULL,'專為低幼兒設計的尋找遊戲。在繽紛的泡泡圖卡中找出指定的圖樣，提升孩子的視覺搜尋能力。'),
	 ('歡樂速配','15-20 min','6+','2-12 人',NULL,'多人同樂的配對遊戲。需在眾多圖案中找出相同的部分，節奏極快，老少咸宜。'),
	 ('多多少少','15 min','6+','2-6 人',NULL,'透過直覺判斷牌面圖案的「多少」，而非精確點數。訓練孩子的數感與快速估算能力。'),
	 ('跑跑龜 (Ribbit)','20 min','6+','3-5 人',NULL,'大家不知道對手是哪隻烏龜。你可以移動自己的，也可以移動別人的（疊在上面一起走）。設法讓自己的烏龜神不知鬼不覺地抵達終點。'),
	 ('石頭湯 (Stone Soup)','20 min','6+','2-6 人',NULL,'改編自知名繪本。大家合作找出成對的食材放入鍋中，必須在爐火熄滅前完成這鍋美味的石頭湯。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('宇宙迷航','30 min','9+','3-5 人',NULL,'玩家共同駕駛太空船避開隕石。每個人負責不同的航行功能，需透過溝通（有時會受限）來達成任務目標。'),
	 ('殭屍貓的試膽大會','20 min','9+','2-6 人',NULL,'可愛又帶點微驚悚。玩家輪流翻開地圖前進，看誰能克服恐懼拿到最多的獎勵，而不被殭屍貓嚇跑。'),
	 ('洗襪子 (Lucky Sock)','15 min','0+','2-6 人',NULL,'襪子怪獸把襪子弄亂了！玩家要從一堆襪子中快速找出成對的組合。是訓練觀察力與組織能力的小遊戲。'),
	 ('OZO王大作戰','20-30 min','9+','2-5 人',NULL,'以獨特角色「OZO」為題，玩家進行資源掠奪與防守，節奏明快且具備一定的策略深度。'),
	 ('星際礦王','30 min','9+','2-4 人',NULL,'在不同星球挖掘稀有礦產。玩家需升級裝備並搶占最佳礦區，是一款具備入門經營概念的遊戲。'),
	 ('快閃冰淇淋 (Go Go Gelato!)','15 min','6+','2-4 人',NULL,'玩家手中拿著甜筒與球，需按照訂單卡快速搬移冰淇淋球（不能用手碰球）。考驗邏輯排序與手眼協調。'),
	 ('搖曳企鵝','15 min','6+','2-6 人',NULL,'將企鵝放置在搖晃的冰山上。小心重心偏移導致冰山翻覆！簡單直接的平衡遊戲。'),
	 ('匹配大師 (Match Madness)','20 min','6+','1-4 人',NULL,'每人一組 5 塊長方體積木。玩家需競速翻轉積木，使其頂面組合出與題目卡完全相同的圖案。'),
	 ('松鼠愛喝湯','15 min','0+','2-2 人',NULL,'專為幼兒與家長設計。透過餵食松鼠喝湯的過程，練習顏色、食材名稱以及基本的大小概念。'),
	 ('龍龍公園','20 min','9+','2-5 人',NULL,'玩家規劃恐龍樂園。透過放置步道與展區，吸引遊客並避免兇猛的龍逃脫。畫風可愛，難度親民。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('下一站：東京 (Next Station: Tokyo)','25-30 min','9+','1-4 人',NULL,'著名的地鐵規劃遊戲續作。玩家在地圖上畫出東京地鐵線，需考慮環狀線連接與換乘站點，非常燒腦精緻。'),
	 ('命懸一線-彩虹版 (The Game: Color)','20 min','9+','2-14 人',NULL,'《數字火車》系列的變體。增加了顏色限制，讓合作排序變得更具挑戰性。支援人數上限極高。'),
	 ('海鹽摺紙 (Sea Salt & Paper)','30 min','9+','2-4 人',NULL,'絕美摺紙藝術風格。玩家收集卡牌發動效果並累積點數，當分數達標時可選擇立即結束或加碼挑戰，節奏明快且有賭博感。'),
	 ('狂飆單車牌','30-45 min','9+','2-5 人',NULL,'模擬自由車大賽。玩家管理體力卡，設法在主集團中「破風」或利用對手的尾流節省體力，最後衝刺奪冠。'),
	 ('工讀生別裝了！','20 min','9+','2-4 人',NULL,'惡搞遊戲。你要觀察周遭行為，抓出那個表現最不像「本尊」的人。充滿台灣網路文化與幽默感的作品。'),
	 ('木林幻境 (LEGENDARY FORESTS)','20 min','9+','2-5 人',NULL,'玩家各自用相同的板塊建造森林版圖。目標是拼湊出完整的色塊區域並在上面種樹，簡單優雅的拼放小品。'),
	 ('天才JUMP熊','15 min','6+','2-6 人',NULL,'根據指令快速讓熊「跳躍」或做出動作。是一款結合觀察與肢體反應的活潑遊戲。'),
	 ('逆流上班族','30 min','12+','3-5 人',NULL,'模擬社畜生活。玩家要在職場混戰中生存，避開老闆的雷區並設法準時下班。充滿職場共鳴的策略遊戲。'),
	 ('得分城市 (Point City)','20-30 min','9+','1-4 人',NULL,'《得分沙拉》團隊續作。將蔬菜換成資源與建築，玩家要在拿取資源與興建城市建築間取得平衡，引擎感更強。'),
	 ('一線勝機','20 min','9+','2-5 人',NULL,'在最後一刻反敗為勝！玩家需精算手牌數值，在緊繃的局勢中尋找唯一的獲勝路徑。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('WHO怕WHO？ Come on！Bite me！','20 min','9+','3-8 人',NULL,'節奏極快的卡牌對決。玩家透過不同的動物牌進行食物鏈比拚，過程充滿意外與笑料。'),
	 ('世界奇觀 (WORLD WONDERS)','50-70 min','12+','1-5 人',NULL,'超華麗的建設遊戲。玩家在版圖上規畫道路與區域，並擺放精美的木製奇觀模型。需兼顧資源管理與空間拼圖。'),
	 ('世界奇觀-夢都擴充','50-70 min','12+','1-5 人',NULL,'增加了更多傳奇的奇觀模型與新的地圖板塊，讓建設過程的選擇更加多樣化。'),
	 ('農場趴踢 (RAMBA ZAMBA)','20 min','9+','2-5 人',NULL,'農場動物們的嘉年華！玩家要避開壞狼、保護雞群，並設法湊齊最多的動物組合獲勝。'),
	 ('瞎掰王-教育版','30-45 min','9+','3-8 人',NULL,'超人氣國產遊戲。一人知道真實定義，其他人都要瞎掰解釋。教育版精選了更多具科學或文化意義的詞彙，邊玩邊學冷知識。'),
	 ('皇家間諜 (Royal Visit)','20 min','9+','2-2 人',NULL,'雙人對戰的神作。玩家透過出牌來移動國王、巫師或弄臣，設法將權力中心拉向自己的城堡。機制簡單但博弈感極強。'),
	 ('3環馬戲團 (3 Ring Circus)','45-75 min','12+','1-4 人',NULL,'玩家扮演馬戲團團長在美國巡迴演出。需招募表演者並在各地建立名聲，美術風格極具美式復古感，策略層次豐富。'),
	 ('永恆之谷 (The Vale of Eternity)','30-45 min','9+','2-4 人',NULL,'近年極受好評的策略遊戲。玩家馴服世界各地的神獸，利用各種能力的連動（Combo）來獲取高分，節奏快且耐玩度高。'),
	 ('胡鬧咖啡廳 (Panic Coffee)','20 min','9+','2-4 人',NULL,'模擬忙碌的咖啡廳現場！玩家需快速應對不斷湧入的訂單，手忙腳亂中還要記住餐點順序，非常適合朋友聚會。'),
	 ('胡鬧咖啡廳-甜點時間擴充','20 min','9+','2-4 人',NULL,'新增了甜點菜單與新的負擔機制，讓原本就混亂的廚房更加熱鬧，適合已經玩過本體的玩家進階挑戰。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('地鐵終點站 (Next Station: London)','25-30 min','9+','1-4 人',NULL,'重現倫敦地鐵規劃。玩家使用四色畫筆輪流畫出線路，需考慮跨河、換乘與景點連接。規則優雅，是紙筆遊戲中的佼佼者。'),
	 ('築夢頌 (Dorfromantik)','30-60 min','9+','1-6 人',NULL,'改編自知名電腦遊戲。玩家合作拼接村莊與森林地景來完成任務，隨著遊戲進行會解鎖新的版塊與秘密內容，非常療癒。'),
	 ('築夢頌-對決 (Dorfromantik: The Duel)','30-45 min','9+','2-2 人',NULL,'將原本的合作模式轉化為雙人競爭。兩位玩家使用相同的版塊，比拚誰能規劃出更高效、更多分的領地。'),
	 ('偽藝術家 (A Fake Artist Goes to New York)','20 min','9+','5-11 人',NULL,'Oink經典款。每人輪流在一張紙上畫一筆。偽藝術家不知道題目，必須觀察別人的筆觸跟著畫而不被抓到。'),
	 ('海底探險 (Deep Sea Adventure)','30 min','9+','2-6 人',NULL,'大家共用一桶氧氣！潛得越深寶藏越好，但移動會消耗氧氣。只要有人貪心不回頭，整船的人都可能窒息，充滿人性考驗。'),
	 ('金蛋雞 (Fafnir)','20 min','9+','2-4 人',NULL,'玩家透過棄掉寶石來換取金蛋。遊戲結束時，持有數量最多的寶石會價值最高，需觀察對手棄掉的顏色來調整策略。'),
	 ('漂流物戰爭 (Flotsam Fight)','20 min','9+','2-6 人',NULL,'類似大老二的跑牌機制。玩家要設法清空手牌，但需根據當前載具的負擔上限來出牌。畫風清新但競爭激烈。'),
	 ('嘿YO (Hey Yo)','15 min','9+','2-10 人',NULL,'附帶一個發聲器的特殊遊戲！玩家需跟著節奏拍子出牌接龍，是一款結合聽覺與反應的超酷炫小品。'),
	 ('知情人 (Insider)','15 min','9+','4-8 人',NULL,'大家猜測正確答案時，其中有一人知道答案但必須隱藏身分並引導大家。猜中答案後要抓出誰是那個「知情人」。'),
	 ('知情人酷黑版 (Insider Black)','15 min','9+','4-8 人',NULL,'知情人的獨立續作。加入了「隨從」角色與更刁鑽的規則，讓推論與誤導的過程更加複雜刺激。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('小早川 (Kobayakawa)','15 min','9+','3-6 人',NULL,'極簡的賭博遊戲。玩家只有一張牌，透過桌面的公共牌「小早川」來加成數值。賭性堅強，節奏極快。'),
	 ('畫不同 (Make the Difference)','20 min','6+','2-5 人',NULL,'你要在原本一樣的圖中親手畫出「細微的差別」。讓大家找不出來太難，太快被找出來也不行，考驗你的繪畫力與觀察力。'),
	 ('假面聯盟 (Maskmen)','20 min','9+','2-6 人',NULL,'摔角手的主題。遊戲開始時沒有顏色強弱，透過玩家出牌的先後順序來定義這一局的點數大小關係。非常聰明的機制。'),
	 ('錢袋 (Moneybags)','20 min','9+','3-6 人',NULL,'強盜分贓現場。玩家要推測每人分到的錢數。如果你拿太少會不甘心，拿太多則會被抓包失去所有錢。'),
	 ('月面探險 (Moon Adventure)','40 min','9+','2-5 人',NULL,'海底探險的合作太空版。玩家在月球表面收集物資，必須在氧氣耗盡前全員回到基地，難度極具挑戰性。'),
	 ('動物荒友會 (Moving Wild)','20 min','9+','1-6 人',NULL,'可愛的動物大遷移。玩家透過輪抽收集動物卡並安排在適合的棲息地。規則簡單但排列策略十足。'),
	 ('臉男 (Mr. Face)','20 min','9+','3-6 人',NULL,'利用簡單的線條五官配件，擺出題目規定的表情。這是一個充滿「笑果」的聯想遊戲，看看誰能理解你那滑稽的臉。'),
	 ('九板塊極限版 (Nine Tiles Extreme)','15 min','6+','2-4 人',NULL,'在九張正反面不同的板塊中快速翻轉出目標圖案。極限版加入了更複雜的顏色與圖形干擾，挑戰反應極限。'),
	 ('瘋狂九板塊 (Nine Tiles Panic)','20 min','6+','2-5 人',NULL,'九板塊的進階版。玩家不只要拼快，還要符合隨機抽出的計分條件（如：這條路要連到外星人），更加燒腦。'),
	 ('忙碌咖啡廳 (Order Overload Café)','20 min','6+','2-6 人',NULL,'玩家輪流複誦菜單上的飲品。隨著層級越高，要記住的訂單就越多。大家合作撐過忙碌的巔峰時段！');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('挑挑揀揀 (Quickity Pickity)','15-20 min','6+','2-5 人',NULL,'在覆蓋的水果片中快速翻找，湊齊相同顏色或種類的組合。節奏非常緊湊的家庭派對遊戲。'),
	 ('筏五人 (Rafter Five)','20 min','6+','1-6 人',NULL,'在搖搖欲墜的木筏上放置船員與貨物板。隨著木筏向外擴張，重心越來越難抓，倒塌的人就輸了！'),
	 ('鑽石快手 (The Diamond Swap)','20 min','9+','3-5 人',NULL,'大家在混亂的珠寶中尋找真鑽。你要盯緊被掉包的瞬間，是一款非常考驗動態視力的遊戲。'),
	 ('番茄番茄番 (Tomatomato)','20 min','6+','3-6 人',NULL,'玩家要快速念出牌陣上的字詞（番、茄、馬、薯...）。當卡片連在一起時，會變成像繞口令一樣的災難，笑果十足。'),
	 ('小鎮66 (Town 66)','15 min','9+','1-4 人',NULL,'在 6x6 的棋盤上放置房屋。每行每列的顏色與形狀都不能重複，玩家要設法放掉手牌，直到有人無法放置為止。'),
	 ('詭計魅影 (Tricks and the Phantom)','15 min','9+','2-4 人',NULL,'每個人都在保護自己的犯人。你要透過線索推理出兇手躲在哪一張卡片背後。玩法精煉且畫風精美。'),
	 ('三思而行 (Troika)','20 min','9+','2-5 人',NULL,'玩家在陌生的星球挖掘寶石（數字卡）。需湊成三張連號或三張同號。是一款結合風險管理與記憶的輕策略遊戲。'),
	 ('微生物 (Zogen)','15 min','6+','2-6 人',NULL,'觀察培養皿中微生物的增減。玩家需大喊出多出來或少掉的微生物名稱並丟牌。是一款會讓人喊到沒力的快節奏遊戲。'),
	 ('推倒提基 (Tiki Topple)','20-30 min','9+','2-4 人',NULL,'玩家有秘密任務，要讓特定的提基木偶留在前三名。透過功能卡將對手心儀的木偶推到最下面或直接剔除。'),
	 ('犯人在跳舞 (The Criminal)','10-20 min','9+','3-8 人',NULL,'極具人氣的傳牌遊戲。犯人牌會不斷在玩家手中流轉。偵探需在結束前抓到犯人，而犯人則要設法在最後一刻留在手中獲勝。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('起司天堂 (Cheese Rescue)','15-20 min','6+','2-4 人',NULL,'貓抓老鼠、老鼠吃起司。玩家要策略性地放置板塊，保護自己的起司不被老鼠吃掉，同時用貓嚇走對手的老鼠。'),
	 ('得寸進尺 (L.L.A.M.A.)','20 min','9+','2-6 人',NULL,'德國年度遊戲獎提名。你要決定繼續出牌清空手牌，還是果斷 Pass 吞下負分。名字寓意「不要讓羊駝帶給你煩惱」。'),
	 ('夜市人蔘 (Yes! Ginseng)','20-30 min','9+','2-5 人',NULL,'以台灣夜市小吃為主題。玩家收集食材製作美味小吃，還要小心別人的奧客卡干擾。是推廣台灣文化的首選桌遊。'),
	 ('夢幻小隊 (Dream Team)','30 min','9+','1-8 人',NULL,'玩家合作建立一支夢幻隊伍。透過間接的線索與默契來達成共識，是一款氣氛溫馨且具社交價值的合作小品。'),
	 ('野生動物園','30 min','9+','1-5 人',NULL,'規劃自己的野生動物保護區。需考慮水源、草地與動物習性，規則簡單但版圖規劃頗有樂趣。'),
	 ('奧地利大飯店 (Grand Austria Hotel)','60-120 min','12+','2-4 人',NULL,'策略玩家心目中的神作。在維也納經營飯店，招待賓客並滿足其需求。需精算資源與骰子點數，競爭感強且成就感十足。'),
	 ('奧地利大飯店-舞動華爾滋','90-120 min','12+','2-4 人',NULL,'飯店本體的大擴充。增加了舞廳機制與更多新角色，讓原本就深厚的遊戲深度更上一層樓。'),
	 ('揭秘希特勒 (Secret Hitler)','45 min','15+','5-10 人',NULL,'極致的社交推理遊戲。玩家分為自由派與法西斯派。法西斯派需隱藏身分並推動邪惡法案。信任與背叛在此遊戲中展現淋漓盡致。'),
	 ('花燈盛會 (Lanterns: The Harvest Festival)','30 min','9+','2-4 人',NULL,'在湖面放置五彩繽紛的花燈。放置方向會讓所有玩家都獲得對應顏色的卡片，需在獲取分數的同時避免讓對手拿太多好牌。'),
	 ('星雲谷 (Via Nebula)','45-60 min','12+','2-4 人',NULL,'玩家合作開拓雲霧中的谷地，但又是競爭建設者的關係。畫風絕美，規則流暢，是典型的歐式輕中度策略。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('逃出馬戲團','20 min','9+','2-6 人',NULL,'馬戲團發生了意外！玩家要利用手上的道具與夥伴，在混亂中率先逃出，充滿突發狀況與互整的樂趣。'),
	 ('解放馬戲團','30 min','9+','2-5 人',NULL,'帶著一點合作與解謎要素，玩家要解開鎖頭並讓受困的動物們獲得自由。適合家庭共遊的主題作品。'),
	 ('布咕布咕 (Buku Buku)','20 min','6+','2-5 人',NULL,'像泡泡一樣繽紛的遊戲。玩家需快速反應並配對正確的顏色與生物圖形，是訓練觀察力的小品。'),
	 ('妖怪百奇八光','30 min','9+','2-4 人',NULL,'以日本百鬼夜行為主題。玩家收集各種妖怪並發動其特殊能力，畫風具有濃厚的傳統日本怪談感。'),
	 ('塗鴉六 (Doodle Dash)','20 min','9+','3-7 人',NULL,'比誰畫得快，也比誰猜得準！每個人同時畫出題目，畫最快的人可以拿最高分，但若畫太爛沒人猜得出來也是沒用的。'),
	 ('全軍出雞','20-30 min','9+','2-4 人',NULL,'玩家率領雞群展開地盤爭奪戰。需透過出牌佈局並預測對手行動，是一款美術可愛但機制紮實的對抗小品。'),
	 ('銀河開拓史','45-60 min','12+','1-4 人',NULL,'玩家在廣袤銀河中殖民行星、研發科技。需在有限的資源下最大化生產力，支援單人遊玩，具有良好的重玩價值。'),
	 ('龍翼翱翔 (Dragonwing)','45-60 min','9+','1-5 人',NULL,'馴服各具特色的巨龍。玩家需根據龍的屬性與技能進行搭配，達成特定的飛行路徑或成就以獲取分數。'),
	 ('薄暮新生','40-60 min','12+','1-4 人',NULL,'在末日後的薄暮世界中重建秩序。結合了資源管理與板塊影響力爭奪，美術風格略帶憂鬱且精美。'),
	 ('遠方海岸','30-45 min','9+','2-4 人',NULL,'玩家探索未知的海岸線。需在航行中平衡補給與發現新資源的風險，是一款節奏輕快的中度策略遊戲。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('HELLOKITTY系列-營火派對','15 min','6+','2-2 人',NULL,'與 HELLO KITTY 一起露營。專為雙人設計，透過簡單的抽牌與配對完成任務，是粉絲不容錯過的療癒小品。'),
	 ('HELLOKITTY系列-午茶約會','20 min','6+','2-5 人',NULL,'熱鬧的午茶時光。玩家需快速找出與目標相符的點心或配件，畫風精美且適合小朋友訓練觀察力。'),
	 ('DOTS','15 min','6+','2-4 人',NULL,'利用不同顏色的圓點進行排列與連線。玩法類似進階版五子棋，需考慮多維度的連線可能性。'),
	 ('海王 舔狗 對的人-基礎聚會版','20-30 min','15+','3-6 人',NULL,'以幽默的感情觀為主題。玩家需判斷對方的身分標籤並進行攻防，充滿各種辛辣話題與垃圾話的派對遊戲。'),
	 ('海王 舔狗 對的人-成人聚會版','20-30 min','18+','3-6 人',NULL,'基礎版的進階「限制級」版本。題目與情境更為大膽刺激，僅適合好友或尺度較大的社交场合。'),
	 ('死灰之冠','60-90 min','12+','1-4 人',NULL,'在灰暗的王國中爭奪王冠。玩家需管理軍隊與資源，並在權力鬥爭中做出抉擇，具有強烈的互動性。'),
	 ('百鬼夜行 (Night Parade of a Hundred Yokai)','40-60 min','9+','1-4 人',NULL,'玩家扮演不同的妖怪首領，率領百鬼巡行佔領領地。畫風精美極致，機制結合了卡牌驅動與版圖控制。'),
	 ('百鬼夜行-咒怨王座擴充','60 min','9+','4 人',NULL,'為本體增加更具侵略性的角色與「咒怨」機制，讓領地爭奪變得更加白熱化。'),
	 ('百鬼夜行-神明崛起擴充','60-70 min','9+','5 人',NULL,'除了支援第 5 位玩家，更引入了「神明」干預機制，提供更強大的行動扭轉局勢。'),
	 ('百鬼夜行-月下低吟擴充','60 min','9+','5 人',NULL,'強化了不同妖怪種族的特殊能力，增加遊戲的非對稱性，讓每場開局都有不同的戰略體驗。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('百鬼夜行-美猴王擴充','60 min','9+','5 人',NULL,'特別版角色擴充。加入強力角色「美猴王」，其獨特的位移與攻擊方式會大幅打亂現有的版圖平衡。'),
	 ('奧爾良大教堂 (Orléans Stories)','90-120 min','12+','2-4 人',NULL,'基於經典遊戲《奧爾良》的進階作品。透過不同章節的故事帶領玩家發展領地，是一款深度的敘事策略桌遊。'),
	 ('派遣小鎮 (Villagers)','30-45 min','9+','2-4 人',NULL,'玩家招募具有不同技能的村民來發展小鎮。需考慮職業間的先後相依關係，美術清爽且思考深度適中。'),
	 ('派遣小鎮-新的使命擴充','45 min','9+','4 人',NULL,'增加多組全新的職人卡牌與特殊成就目標，為原有的連鎖機制帶來更多變化的可能性。'),
	 ('四季仙靈 (PIXIES)','20-30 min','9+','2-5 人',NULL,'《水果沙拉》團隊的作品。玩家在 3x3 的版圖中放置仙靈卡片，需考慮數字排列與顏色對應，是一款精緻的高互動小品。'),
	 ('阿瓦隆-新未來版 (Quest)','30 min','12+','5-10 人',NULL,'《阿瓦隆》的正統進化版。簡化了投票流程，增加了更多強力的特殊身分，節奏更快且讓推理過程更聚焦。'),
	 ('遙遠之地 (Faraway)','20-30 min','9+','2-6 人',NULL,'極具創意的倒敘計分機制。玩家先放下探險卡，最後必須「由後往前」計算分數，這讓出牌順序變得極其關鍵且反直覺。'),
	 ('呃話不說 (Ami-Moji)','20 min','9+','4-10 人',NULL,'不能說話！玩家需利用簡單的符號或 Emoji 來傳達抽象的詞彙或情緒。看看大家的默契與腦洞是否在同個頻率上。'),
	 ('同房異夢 (Dream On!)','20 min','9+','2-4 人',NULL,'玩家合作共同編織一個荒誕的夢境。當計時結束後，全體需憑記憶共同重述夢境的細節，是一款溫馨且考驗想像力的遊戲。'),
	 ('同房異夢-遷居新夢','20 min','9+','2-2 人',NULL,'新增了與搬家、新環境相關的夢境卡牌，增加了更多有趣的圖像元素與敘事點。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('夜幕降臨 (Everdell)','60-90 min','12+','2-5 人',NULL,'（註：此指《仙境幽谷》）玩家在古老的樹林中建設城市。結合精美的立體大樹配件與極佳的策略深度，是現代桌遊的顏值與內涵擔當。'),
	 ('可可亞 (Cacao)','45 min','9+','2-4 人',NULL,'經典的板塊放置遊戲。玩家透過拼放工人板塊與叢林板塊來獲取可可豆、灌溉農田並去市場買賣，機制優雅流暢。'),
	 ('可可亞-黃金國擴充','60 min','9+','4 人',NULL,'為本體帶來了新的「黃金國」地圖板塊與相關神廟，增加了更多元的分數獲取途徑。'),
	 ('估估劃劃-嗨起來 (Alias Party)','45-60 min','12+','4-100 人',NULL,'經典描述遊戲進階版。玩家需在搞笑的特殊限制（如：單腳站立、假裝大笑）下描述詞彙讓隊友猜。笑果爆炸。'),
	 ('估估劃劃-台灣版 (Alias Taiwan)','45-60 min','9+','4-100 人',NULL,'收錄了大量台灣在地詞彙（如：珍奶、台灣黑熊、捷運）。更貼近本土生活，非常適合各年齡層聚會。'),
	 ('萬貓的慶典','30 min','9+','3-4 人',NULL,'在充滿貓咪的廟會中進行祭典。玩家需收集指定的貓咪組合來達成成就，畫風非常精緻可愛。'),
	 ('滑冰企鵝-魔法學園','20 min','6+','2-4 人',NULL,'企鵝們在冰上滑行！結合簡單的體感元素與任務卡，看誰能最快在學園中完成魔法訓練。'),
	 ('解碼傳說-黑鬍子的秘寶','30-45 min','9+','1-4 人',NULL,'一系列劇本式解謎遊戲。玩家需解讀黑鬍子船長的暗號來找出寶藏位置，考驗觀察力與聯覺能力。'),
	 ('解碼傳說-彩虹之心','30-45 min','9+','1-4 人',NULL,'延續解碼機制，以充滿奇幻彩虹色彩的故事情節為背景，謎題難度適中，適合親子共同燒腦。'),
	 ('異形代號24 (Codenames: Duet)','15-20 min','9+','2-2 人',NULL,'《機密代號》的專屬雙人合作版。兩位玩家互相給予提示，設法在有限回合內點出所有正確目標並避開暗殺者。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('人生二周目','30-45 min','12+','2-6 人',NULL,'如果人生可以重來？玩家在第二輪生命中重新選擇職業、技能與人脈，體驗截然不同的命運路徑。'),
	 ('窒命玩笑 (Joking Hazard)','20-30 min','18+','3-10 人',NULL,'知名網漫《Cyanide & Happiness》改編。玩家需用手牌拼接出最荒誕、最令人窒息的漫畫結尾。地獄梗愛好者首選。'),
	 ('森靈之道 (Forest Shuffle)','45-60 min','9+','1-4 人',NULL,'玩家在森林中放置樹木、昆蟲與動物。特殊的左右上下插槽出牌機制，讓卡牌之間的生態連結變得極具策略層次。'),
	 ('森靈之道-妖靈食堂擴充','60 min','9+','4 人',NULL,'為原本寫實的森林加入了神祕的妖靈生物，增加了更多強力且多樣的食物鏈互動方式。'),
	 ('落葉翩翩 (Leaves)','30 min','9+','1-4 人',NULL,'將秋天的落葉拼湊成美麗的版圖。規則優美如拼圖，考驗玩家如何在不規則形狀中達成最大覆蓋。'),
	 ('藝術名流 (Modern Art)','45 min','9+','2-4 人',NULL,'（註：此指經典遊戲《現代藝術》）玩家扮演畫廊老闆進行五種不同形式的拍賣。炒作藝術家的身價並在高點脫手獲利。'),
	 ('利伯塔利亞：自由之風 (Libertalia)','45-60 min','12+','1-6 人',NULL,'海盜分贓遊戲。所有玩家擁有完全相同的手牌，你需預測對手出牌順序，在每天的分贓中搶奪最高價值的寶藏。'),
	 ('分秒必爭','20 min','9+','3-5 人',NULL,'這是一個考驗時間體感與反應速度的遊戲。玩家要在極短的時間內做出決策，慢了一秒可能就失去一切。'),
	 ('惡魔電梯 (Devil''s Elevator)','30-40 min','9+','1-4 人',NULL,'玩家受困在失控的電梯中。需透過環境線索解開每一層樓的機關與謎題，具有強烈的代入感。'),
	 ('巧手猜圖 (PICTURES)','30 min','9+','3-6 人',NULL,'2020年德國年度遊戲。利用鞋帶、彩色方塊或樹枝等簡陋配件「重現」照片上的內容。充滿想像力與笑點。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('蕯凡納公園 (Savannah Park)','30-40 min','9+','1-4 人',NULL,'玩家在非洲大草原搬動動物板塊。每人只有一次翻面機會，需將同種動物聚攏並圍繞水源，規則簡單卻極具策略挑戰。'),
	 ('白教堂血案 (Letters from Whitechapel)','90-120 min','15+','2-6 人',NULL,'一人扮演開膛手傑克，其他人扮演警察。傑克在隱藏地圖上移動，警察需根據線索封鎖道路，展開一場驚心動魄的貓捉老鼠。'),
	 ('聖母院 (Notre Dame)','45-75 min','12+','2-5 人',NULL,'經典德式策略。玩家在巴黎街道建設區域，需平衡獲取分數與抵禦老鼠（瘟疫）的威脅，策略連動感強烈。'),
	 ('方格都市 (Quadropolis)','45-60 min','9+','2-4 人',NULL,'玩家扮演城市規劃師。透過特殊的建築師放置機制來拿取板塊，需考慮工業、商業、住宅與公園的配置加成。'),
	 ('瘋狂山脈 (Mountains of Madness)','60-90 min','12+','3-5 人',NULL,'改編自洛夫克拉夫特的小說。玩家合作攀登高峰，但隨著海拔升高，玩家會抽到「發瘋卡」，必須在溝通時做出奇怪的行為（如：不能看對方的臉、說話要帶髒話），非常爆笑且具備挑戰性。'),
	 ('穆拉諾光影大師 (Murano: Light Masters)','30-45 min','9+','2-4 人',NULL,'以威尼斯玻璃島為背景。玩家轉動環型轉盤來獲取彩色的玻璃碎片，完成美麗的工藝品訂單。配件非常漂亮，是一款賞心悅目的輕策略。'),
	 ('聖瑪利亞 (Santa Maria)','45-90 min','12+','1-4 人',NULL,'經營自己的美洲殖民地。玩家透過選取骰子來驅動整行或整列的建築產出資源，規則環環相扣，是非常紮實的德式策略遊戲。'),
	 ('聖瑪利亞-美洲王國擴充','90 min','12+','5 人',NULL,'增加了瑪雅神廟、總督模組以及支持到第五位玩家。為原本的規劃路線增加了更多變數與策略深度。'),
	 ('雷克斯：帝國之末日 (Rex: Final Days of an Empire)','120-180 min','15+','3-6 人',NULL,'經典遊戲《沙丘 (Dune)》的重製版，背景改為 FFG 的《暮光帝國》宇宙。玩家在破碎的首都爭奪控制權，充滿背叛、秘密結盟與慘烈的戰爭。'),
	 ('獵人與偵查兵 (Jäger und Späher)','20-30 min','9+','2-2 人',NULL,'兩位部落首領帶領族人狩獵與探險。需妥善分配隊員去收集物資或進行偵查，是一款小而美的雙人博弈遊戲。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('年獸','20-30 min','9+','3-3 人',NULL,'以傳統習俗「年獸」為背景。玩家需設法利用鞭炮、紅紙等道具來防禦年獸的襲擊，具有強烈的節日氛圍。'),
	 ('仙境戰記 (Wonderland''s War)','45-125 min','12+','2-5 人',NULL,'在愛麗絲夢遊仙境的世界中展開內戰。玩家在茶會上招募夥伴（塞入袋中），然後在戰鬥區比拼運氣與戰力。配件極其豪華。'),
	 ('仙境戰記-瘋狂碎片擴充','125 min','12+','5 人',NULL,'增加了更多瘋狂碎片模組與新角色，讓戰鬥過程中的副作用與報酬變得更不可預測。'),
	 ('希望樂園 (Hope Harbor)','45 min','9+','2-4 人',NULL,'在遭受災害後的港口進行重建。玩家需修復建築並妥善規劃資源流動，是一款充滿正能量與建設成就感的作品。'),
	 ('澳洲天劫 (AuZtralia)','30-120 min','15+','1-4 人',NULL,'故事設定在 1930 年代的澳洲。玩家建設鐵路、開採資源，但同時克蘇魯舊日支配者會在地圖上醒來並發起攻擊。玩家需平衡競爭與共同抵禦古神。'),
	 ('托斯卡納城堡 (The Castles of Tuscany)','45-60 min','9+','2-4 人',NULL,'由《柏根第城堡》作者設計。簡化了繁雜的規則，但保留了拼放領地與獲取連動效果的快感，是極佳的中輕度德式桌遊。'),
	 ('神秘谷 (Mystic Vale)','45 min','9+','2-4 人',NULL,'創新的「卡牌打造」系統。玩家不只是買新卡，而是購買「透明膠片」插進卡套裡來強化卡片，玩法獨一無二。'),
	 ('花舍物語 (Cottage Garden)','45-60 min','9+','1-4 人',NULL,'《拼布藝術》作者三部曲之一。玩家在苗圃中拼湊多樣形狀的花卉板塊，目標是填滿土地獲取高分。畫風溫馨療癒。'),
	 ('暖秋物語 (Indian Summer)','45-60 min','9+','1-4 人',NULL,'三部曲之二。主題轉向秋天的落葉，加入了更多連動寶藏的機制，比起《花舍物語》多了一點策略複雜度。'),
	 ('玖陣王國 (Nine Realms)','45-60 min','12+','2-5 人',NULL,'以北歐九大國度為背景。玩家爭奪不同維度的控制權，需考慮國度間的連動效果與神祇的力量。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('535','20 min','9+','2-6 人',NULL,'一款極具深度的跑牌遊戲。規則核心圍繞著「5、3、5」的出牌限制，玩法結合了大老二的直覺與數值計算的嚴謹。'),
	 ('迷宮美食家','30 min','9+','2-5 人',NULL,'玩家深入迷宮尋找頂級食材。需避開怪物並與其他美食家競爭，畫風充滿奇幻RPG風格。'),
	 ('生活日長','30-45 min','9+','1-6 人',NULL,'模擬日常生活中的各種瑣事與決策。幫助孩子建立金錢觀與時間管理概念，是一款具備教育意義的家庭桌遊。'),
	 ('汪喵撲克','15 min','6+','2-4 人',NULL,'將傳統撲克與可愛的貓狗元素結合。玩法快節奏，適合小朋友練習基礎的牌組配對與數字識別。'),
	 ('迷宮逃亡-拉比林托斯','15 min','9+','1-1 人',NULL,'單人挑戰迷宮。玩家需在不斷變化的通道中找出出口，考驗空間邏輯與耐心。'),
	 ('迷宮逃亡-阿里阿德涅','15 min','9+','1-1 人',NULL,'《迷宮逃亡》系列作。難度更高，加入了特殊機關，玩家需像希臘神話般巧妙利用線索逃脫。'),
	 ('羅密歐與茱麗葉 IF故事線','30-45 min','12+','3-6 人',NULL,'基於經典悲劇發展的「如果」劇本。玩家扮演家族成員，設法改變兩人的命運或守護家族榮耀。'),
	 ('溫泉繁盛記 (Hot Springs Story)','45-60 min','9+','1-4 人',NULL,'經營自己的溫泉旅館。規劃浴池、客房與販賣部，吸引不同類型的客人來賺取金錢與評價。'),
	 ('溫泉繁盛記 擴充','60 min','9+','4 人',NULL,'增加了更多特殊季節事件與華麗的設施，讓經營過程中的連動與排版更加多樣化。'),
	 ('忍者之儀 (Ninja Ritual)','20 min','9+','2-4 人',NULL,'玩家需快速做出規定的忍者結印手勢。是一款非常考驗反應與身體協調性的派對遊戲。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('佑廟靈簽','20-30 min','9+','3-6 人',NULL,'以台灣宮廟文化為主題。玩家求取靈籤、祭拜神明，是一款帶有濃厚在地信仰色彩的輕策略遊戲。'),
	 ('瓦拉多冒險記','45 min','9+','2-5 人',NULL,'組建你的英雄隊伍深入瓦拉多。結合了擲骰與卡牌戰鬥，節奏明快且具有豐富的奇幻風格。'),
	 ('魔物討伐隊','30 min','9+','2-4 人',NULL,'玩家合作對抗不斷湧現的魔物。需精算手牌數值與發動合擊技，適合喜歡打怪主題的小型團體。'),
	 ('決戰阿瓦隆 (Avalon Battle)','30-45 min','12+','3-6 人',NULL,'非社交推理類的阿瓦隆。而是以亞瑟王傳說為背景的卡牌攻防戰，玩家使用角色技能爭奪聖盃。'),
	 ('暗貨 (Dark Goods)','30-45 min','12+','3-5 人',NULL,'玩家在黑市中走私貨物。需觀察對手的報價與神情，決定是否攔截或交易。充滿心機與風險的小品。'),
	 ('馬約利卡 (Majolica)','45 min','9+','2-4 人',NULL,'台灣設計師作品。以精美的瓷磚花紋為題，玩家需策略性地安排瓷磚掉落與連鎖反應。配件極具美感。'),
	 ('國富論 (Wealth of Nations)','120-180 min','15+','3-6 人',NULL,'極致硬核的經濟遊戲。玩家需建設各類工廠、管理資源流動，並在波動的市場中與對手交易。完美模擬了亞當斯密的經濟理論。'),
	 ('國富論-戰爭風雲擴充','180 min','15+','6 人',NULL,'為原本和平的貿易世界加入了軍事衝突。玩家可以用武力掠奪土地或摧毀對手的工業鏈。'),
	 ('國富論-超級產業板塊擴充','180 min','15+','6 人',NULL,'增加了高產量但也極其昂貴的超級工廠，讓遊戲後期的經濟規模呈倍數成長。'),
	 ('雪山畫策','30 min','9+','1-4 人',NULL,'玩家需在險惡的雪山上進行規劃，透過棄牌與拿牌的權衡，在有限的回合內達成登頂目標。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('血契獵殺 (Blood on the Clocktower)','60-120 min','15+','6-12 人',NULL,'被譽為推理遊戲的天花板。每人都有特殊技能，死後仍能發揮影響力，搭配一位說書人主持。是目前最火紅的大型派對遊戲。'),
	 ('選汪與喵 (Pick a Dog / Pick a Cat)','15 min','6+','3-5 人',NULL,'在桌面上尋找與自己手中卡片僅有一項差異（顏色、大小、姿勢）的下一張牌。速度極快，考驗視覺過濾能力。'),
	 ('三藩之亂','15 min','12+','1-1 人',NULL,'單人歷史模擬遊戲。玩家需在三藩之亂的動盪局勢中進行佈局，設法維持清朝政權或反擊。'),
	 ('暴走汪汪','20 min','6+','2-4 人',NULL,'狗狗失控啦！玩家需透過簡單的道具與運氣來攔截逃跑的狗狗，適合全家大小一起瘋狂大笑的遊戲。'),
	 ('神探緝兇2','15-20 min','9+','2-2 人',NULL,'經典推理遊戲續作。一位玩家佈下線索，另一位需透過邏輯排除法找出真正的兇手藏身處。'),
	 ('皮納塔派對 (Piñata Party)','15 min','6+','2-5 人',NULL,'模擬墨西哥傳統派對。玩家敲打皮納塔獲取裡面的糖果卡片，是一款輕鬆幽默、色彩鮮艷的作品。'),
	 ('腦洞連線','20 min','9+','3-8 人',NULL,'玩家需在完全無關的兩張圖案中找出一個奇妙的共通點讓大家猜中。你的腦袋轉得跟別人一樣快（或是怪）嗎？'),
	 ('極簡畫家','20 min','9+','3-6 人',NULL,'題目很複雜，但你只能用極少數的線條（甚至是一個幾何圖形）來呈現。看誰是真正的極簡主義大師。'),
	 ('恐龍扛浪','20 min','9+','2-6 人',NULL,'結合網路流行語的趣味桌遊。玩家需跟著節奏做出動作或出牌，是一款純粹為了炒熱氣氛而生的遊戲。'),
	 ('搜查瑠公圳','30-45 min','12+','2-6 人',NULL,'以台灣清代著名水利工程「瑠公圳」為舞台的推理遊戲。玩家調查水圳發生的懸案，同時了解在地歷史文化。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('貪吃麻吉狗','15 min','6+','2-4 人',NULL,'幫貪吃的狗狗找食物。透過記憶食物卡的位置來餵食狗狗，是適合學齡前兒童訓練短期記憶的作品。'),
	 ('爆爆椰 (COCO BOOM)','15 min','6+','2-5 人',NULL,'充滿動感的派對小品。玩家需快速拍打或接住彈出的椰子配件，場面非常混亂刺激。'),
	 ('LEO獅子剪髮大冒險','20 min','6+','2-5 人',NULL,'這是一場與時間賽跑的記憶挑戰！獅子利奧的頭髮太長了，玩家要合作記住森林的路徑，在理髮廳關門前帶牠去剪頭髮。'),
	 ('阿姆利則：金光聖廟 (Amritsar: The Golden Temple)','60-120 min','12+','1-4 人',NULL,'玩家在印度阿姆利則建設著名的金廟。核心機制是創新的播種（Mancala）移動方式，需精算資源與行動步數，美术風格極具異國情調。'),
	 ('托爾圖加2199 (Tortuga 2199)','60-90 min','12+','2-4 人',NULL,'玩家扮演太空海盜，在遙遠星系中爭奪霸權。結合了 DBG（牌庫構建）與版圖移動，可以升級飛船並佔領空間站，戰鬥感十足。'),
	 ('BEEZ 蜜蜂物語','30-45 min','9+','2-4 人',NULL,'玩家控制小蜜蜂在花叢中採集花粉。移動方式受到限制，需預算飛行路徑並收集特定顏色的花粉以完成任務。配件蜜蜂模型非常可愛。'),
	 ('福爾摩斯探案：莫里亞蒂的天羅地網','45-60 min','12+','3-6 人',NULL,'玩家需在倫敦街道追蹤教授的蹤跡。在推理真相的同時，也要小心同伴中是否有人已被收買。充滿懸疑感的英倫風格作品。'),
	 ('小小鐵路帝國 (Tiny Epic Railroads)','30-60 min','9+','1-4 人',NULL,'「小小系列」作品之一。在微型盒子裡完整重現了建設鐵道、運送貨物與發展城市的深度，空間利用率極高的硬核策略。'),
	 ('QE 量化寬鬆','45 min','9+','3-5 人',NULL,'你扮演國家銀行，擁有無限的印鈔權！拍賣時你可以填寫任何數字，但遊戲結束時，印最多錢（花最多）的玩家直接淘汰。節奏瘋狂且諷刺感十足。'),
	 ('魚樂無窮','20 min','6+','2-5 人',NULL,'繽紛的海底世界。玩家收集各種魚類拼湊出自己的水族箱，適合喜愛海洋生物的小朋友。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('寵物急診室','20 min','9+','3-5 人',NULL,'玩家扮演獸醫，需快速根據寵物的病症卡配對藥品與治療方式。緊張刺激且充滿可愛動物元素。'),
	 ('Gnomopolis 矮人總動員','45 min','9+','1-4 人',NULL,'從布袋中抽取矮人勞動力來建設矮人都市。不同顏色的矮人有不同專長，玩家需妥善安排住處與工作空間。'),
	 ('2045','30-45 min','12+','3-5 人',NULL,'台灣原創作品。設定在未來的 2045 年，玩家在近未來城市中進行資源分配與勢力競爭，具有強烈的美術風格與本土開發的策略思維。'),
	 ('搶救甜點公主','20 min','9+','3-5 人',NULL,'玩家合作通過充滿甜點障礙的迷宮。需運用記憶力與團隊溝通來避開陷阱，是一款節奏輕快、氛圍甜蜜的作品。'),
	 ('閱讀空氣究極二選一','20 min','12+','3-8 人',NULL,'改編自日本經典遊戲。玩家要針對尷尬或奇特的情境做出選擇，看看你的回答是否符合大眾的「空氣（氛圍）」，充滿日式幽默。'),
	 ('粉墨登場','30 min','9+','3-5 人',NULL,'以劇場表演為背景。玩家需招募演員、準備服裝並安排劇目，是一款主題感鮮明、帶有成套收集要素的輕策略遊戲。'),
	 ('奇妙藏館','30-45 min','9+','1-5 人',NULL,'規劃自己的私人博物館。需安排展品的陳列位置以吸引遊客，是一款著重視覺美感與空間配置的作品。'),
	 ('橫豎 THE MASTER','15 min','9+','2-2 人',NULL,'簡約而不簡單的抽象對戰遊戲。玩家需在橫向與縱向的攻防中尋求突破點，適合喜歡純粹腦力博弈的玩家。'),
	 ('地城對決 (Dungeon Duel)','20 min','9+','2-2 人',NULL,'雙人快速對戰。玩家各自率領冒險者或魔物在地下城展開遭遇戰，機制快節奏且充滿戰術變化。'),
	 ('冒險少女公會','30 min','9+','2-4 人','bg_1774760502261.jpeg','經營公會並招募少女冒險者。需分配任務並平衡資源，畫風精美，具有輕度經營模擬的趣味。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('花園棋 (Garden)','20 min','9+','2-2 人',NULL,'雙人版圖遊戲。透過放置花卉棋子爭奪領地，規則優雅平衡，像是一場在花園中的圍棋對弈。'),
	 ('謝謝招待 (Dinner''s On You)','15-20 min','9+','2-5 人',NULL,'吃飯要付錢，但誰付？玩家透過出牌與心理博弈，設法將帳單推給對手，是一款非常適合餐桌聚會的幽默小品。'),
	 ('香蕉保衛戰','15 min','6+','3-5 人',NULL,'猴子搶香蕉！玩家需快速反應並爭奪桌面上的香蕉配件，是一款能瞬間引爆氣氛的競速遊戲。'),
	 ('究極獎池大挑戰','30 min','9+','2-4 人',NULL,'模擬抽獎與累計獎金。玩家需決定何時收手，何時繼續投入，考驗對機率的直覺與對抗慾望的能力。'),
	 ('天際之塔','30 min','9+','2-4 人',NULL,'玩家疊放不規則的建築組件來建造高塔。重心偏移就可能崩塌，結合了物理平衡與戰略卡位。'),
	 ('CAT 與貓的距離','20 min','9+','2-6 人','bg_1774760466811.jpeg','測量你與貓（或對手）的心靈距離！透過對特定情境的喜好投票，找出誰才是你最契合的夥伴。'),
	 ('三影成趣','15 min','9+','1-2 人',NULL,'特殊的視覺遊戲。玩家需觀察物體在不同光源下的投影，並推導出物體的真實排列方式。'),
	 ('天才考手','20-30 min','9+','4-8 人',NULL,'考驗反應速度與多工處理。玩家需一邊處理指令，一邊觀察場上變化，場面混亂且充滿笑料。'),
	 ('姬路城 (The White Castle)','45-70 min','12+','1-4 人',NULL,'2023年大作。玩家在著名的姬路城進行外交、修練與資源收集。遊戲只有三輪，每一步都極其關鍵，是當前最熱門的中度策略。'),
	 ('姬路城-茶道擴充','70 min','12+','4 人',NULL,'增加了茶道室版塊與相關行動，為原本緊湊的步數增加更多變化與分數來源。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('魔王地下城 (One Deck Dungeon)','30-45 min','9+','1-4 人',NULL,'（註：通常指一疊地城）用極少的配件模擬豐富的地城探險。玩家升級技能並透過分配骰子擊敗魔王，具備極強的重玩性。'),
	 ('鐵道任務：紐約 (Ticket to Ride: New York)','10-15 min','9+','2-4 人',NULL,'經典系列的最速版。改用計程車在紐約街道穿梭，保留了核心的樂趣，但可在 15 min內結束一場。'),
	 ('飯捲達人','20 min','6+','2-4 人',NULL,'收集各種食材卡來製作美味的韓式飯捲。規則單純且畫風溫馨，非常適合親子共讀共玩。'),
	 ('狼爾街風雲','30-45 min','12+','3-11 人',NULL,'結合了金融市場與社交博弈。玩家在市場波動中尋求最大利益，必要時得靠口才與詐唬來影響對手。'),
	 ('紅龍酒館 (The Red Dragon Inn)','30-60 min','12+','2-4 人',NULL,'冒險者們打完仗後在酒館喝酒、賭博。誰能留到最後不醉倒且不破產就是贏家，角色充滿個性與幽默。'),
	 ('連環喋血','30 min','15+','2-4 人',NULL,'玩家需拼湊案發現場的蛛絲馬跡。具有較強的敘事性，適合喜歡冷調偵探風格的玩家。'),
	 ('未知行星 (Planet Unknown)','60-80 min','9+','1-6 人',NULL,'2023年大作。玩家利用巨大的旋轉盤同時選取板塊，在各自的行星上進行建設。零等待時間的設計讓多人遊戲依然順暢。'),
	 ('無罪之證','30 min','12+','2-5 人',NULL,'身陷嫌疑的玩家需設法洗清罪名。透過交換情報與邏輯推論找出真正的證物，節奏緊湊。'),
	 ('醉闖地域','20-30 min','15+','2-6 人',NULL,'帶著酒意的冒險！玩家在充滿陷阱的地圖中前行，這款遊戲往往伴隨著幽默的逞罰與誇張的轉折。'),
	 ('火車嘟嘟','15 min','6+','2-4 人',NULL,'專為小朋友設計的火車接龍。透過辨識火車廂的顏色或符號進行配對，訓練幼兒的專注力。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('石來運轉','30 min','9+','1-5 人',NULL,'收集與排列美麗的寶石。玩法具有一定的隨機性，但如何妥善運用每一顆石頭達成目標則考驗策略。'),
	 ('超級無敵幸運星 (Super Mega Lucky Box)','20 min','9+','1-6 人',NULL,'快節奏的數字填寫遊戲。類似進階版賓果，連線後會觸發各種強大加成，讓你有「爽快連擊」的感覺。'),
	 ('密弒派對','45-60 min','15+','2-6 人',NULL,'在派對的外衣下隱藏著密室逃脫的機制。玩家需解開現場的謎題才能安全「離場」，代入感極強。'),
	 ('音韻園鰻','20 min','9+','1-5 人',NULL,'以超人氣生物「花園鰻」為主題。結合節奏感與視覺辨識，是一款畫面與玩法都非常療癒且有趣的遊戲。'),
	 ('三步成堡 (Kingdomino)','15-20 min','9+','1-6 人',NULL,'（註：通常指多米諾系列）玩家選取地型板塊拼放在自己的王國。規則簡單但計分精確，是入門桌遊的首選。'),
	 ('坐以待斃 (Stay Cool)','20 min','12+','3-6 人',NULL,'極致的感官轟炸！你要同時回答兩個人的問題，一個用嘴巴答，一個用骰子拼，還要注意沙漏的時間。讓你大腦當機的有趣遊戲。'),
	 ('皇冠拉米牌 (Five Crowns)','45 min','9+','2-4 人',NULL,'經典卡牌遊戲。擁有五種花色，且每一輪的「鬼牌」都會變動，規則多變且耐玩。'),
	 ('十分機靈 (10 Out of 10)','15-20 min','9+','2-10 人',NULL,'一款簡單輕快的數學運算遊戲，玩家需透過加減法讓手中數字盡可能接近 10，非常適合訓練小朋友的基礎心算。'),
	 ('黃牌 (Yellow Cards)','20-45 min','18+','4-10 人','bg_1774760308489.jpeg','台灣原創的填詞遊戲。由一名玩家擔任裁判出題，其他玩家用手中的「垃圾話」卡片填空，內容通常極具惡搞與無節操風格。'),
	 ('步步為營 (Quoridor)','15-20 min','9+','2或4 人',NULL,'玩家需設法將自己的棋子走到對手底線。每回合可以選擇移動棋子或放置木板阻擋對手，但不能完全封死對方的路。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('小羊躲妙妙 (Go Away Monster!)','10-15 min','0+','2-4 人',NULL,'專為幼兒設計的合作遊戲。孩子們要在袋子中摸索家具形狀來佈置房間，如果摸到怪物就要大喊「怪物走開」並將其丟掉。'),
	 ('跳跳棋 (Chinese Checkers)','20-30 min','6+','2-6 人',NULL,'經典的棋盤遊戲。玩家透過連續跳躍的方式，最快將所有棋子移動到對角陣地的玩家獲勝。'),
	 ('跳跳骰 (Bounce-Off)','15 min','6+','2-4 人',NULL,'玩家需將乒乓球在桌上反彈一次後進入網格中，率先達成挑戰卡上的排列圖案（如四連線或正方形）即得分。'),
	 ('格格不入 (Blokus)','20-30 min','6+','2-4 人',NULL,'俄羅斯方塊風格的領域占領遊戲。規則只有一個：新放的方塊必須與自己的方塊「角對角」相接，不能邊對邊。'),
	 ('諾亞方舟 (Noah''s Ark)','15-30 min','0+','1-6 人',NULL,'考驗手部的穩定度。玩家需輪流抽取動物卡，並將對應的動物模型擺放到搖晃的方舟上，弄翻方舟的人就輸了。'),
	 ('伐木工 (Toc Toc Woodman)','10-15 min','6+','2-7 人',NULL,'玩家用斧頭敲擊樹幹，目標是敲下樹皮得分，但如果用力過猛敲下樹幹核心則會扣分，是一款極具緊張感的動作遊戲。'),
	 ('估估劃劃 (Alias)','30-45 min','9+','4-10 人',NULL,'分組競爭遊戲。在限時內，隊員要用各種描述、近義詞或反義詞讓隊友猜出卡牌上的詞彙，但不能直接說出謎底文字。'),
	 ('估估劃劃-兒童版','20-30 min','6+','4-10 人',NULL,'專為兒童設計，謎題卡片附有精美插圖，即便還不識字的小朋友也能透過圖片進行描述與聯想。'),
	 ('卡坦島-5-6人擴充','90-120 min','9+','5-6 人',NULL,'增加了額外的版圖與配件，讓原本只能 4 人遊玩的卡坦島支援到 6 人。'),
	 ('DC超級英雄 (DC Spyfall)','30-45 min','9+','2-5 人',NULL,'利用英雄角色的特殊能力進行對抗，設法在戰鬥中擊敗對手並累積聲望分數。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('燈塔巡航','30 min','9+','1-4 人',NULL,'控制船隻在燈塔間巡航。玩家需避開暗礁並妥善規劃航線以收集補給，遊戲氛圍平靜且考驗空間邏輯。'),
	 ('米莫漢堡','15 min','6+','2-4 人',NULL,'疊漢堡大挑戰！玩家需快速反應並根據訂單疊出正確的漢堡順序，是款充滿歡樂氣氛的體感遊戲。'),
	 ('生日快快樂','20 min','6+','2-6 人',NULL,'充滿慶祝氣氛的遊戲。玩家透過簡單的卡牌互動來收集派對物品，非常適合在小朋友生日會上遊玩。'),
	 ('棉花糖試驗 (Marshmallow Test)','20 min','9+','2-5 人',NULL,'由大師 Reiner Knizia 設計。玩家在吃墩遊戲中要忍住不拿太早，因為越晚拿到墩數的人分數越高，完美呼應心理學實驗。'),
	 ('搖擺快找王','15 min','6+','2-10 人',NULL,'大團體也能玩的反應遊戲。在混亂的圖案中找出目標，搖搖晃晃的組件讓找尋過程更有難度。'),
	 ('沉睡皇后 (Sleeping Queens)','20 min','6+','2-5 人',NULL,'由 6 歲女孩發明的經典。玩家出牌來喚醒沉睡的皇后，同時要防範對手的騎士來搶奪，是無數家庭的啟蒙桌遊。'),
	 ('金曲猜歌王','30-45 min','12+','2-10 人',NULL,'音樂愛好者的派對聖經。僅憑前奏或幾個音符來猜歌名，收錄大量華語金曲，能瞬間讓現場變成卡拉 OK。'),
	 ('吸爆鬆餅 (Muffin Time)','20-40 min','12+','2-8 人',NULL,'來自網路動畫的惡搞風格。這是一個「沒有規則就是規則」的混亂遊戲，充滿各種陷阱卡與莫名其妙的勝負點，適合瘋狂的朋友。'),
	 ('和諧之森 (Harmony Forest)','30 min','9+','1-4 人',NULL,'玩家合作或競爭佈置森林。需考慮動物與植物的共生關係，畫面優美且規則流暢。'),
	 ('掌握時刻 (TAKE TIME)','20 min','9+','2-4 人',NULL,'這是一個考驗時間體感的遊戲。玩家需在不看鐘的情況下，精確判斷時間的流逝，挑戰你的生理時鐘。');
INSERT INTO public."boardGames" ("name","time",age,people,img,"content") VALUES
	 ('七翻天 (FLIP 7)','20 min','9+','3-10 人',NULL,'簡單暴力！翻開卡片累積數字，只要不翻到重複的數字或特定的陷阱就能一直翻。非常適合多人聚會熱身。'),
	 ('卡米諾 (Camino)','30 min','9+','1-6 人',NULL,'連鎖反應式的板塊鋪路遊戲。玩家需設法連通自己的起點與終點，同時阻礙對手，玩法直覺有趣。'),
	 ('心靈圖解任務','30 min','9+','4-10 人',NULL,'玩家合作將抽象的圖案與詞彙進行連結。這是一個考驗團隊默契與圖像化思考的溫馨小品。'),
	 ('終點攝影：最後衝刺 (PHOTOFINISH)','20 min','6+','2-6 人',NULL,'觀察衝線瞬間的照片！玩家需在極短時間內判斷誰才是真正的冠軍，考驗觀察力與快門式的視覺辨認。');
